435	    const durationMs = run.durationMs ?? t - run.startedAt;
436	
437	    this.db.transaction(() => {
438	      this.flushRun(run);
439	      this.updateRunTotals.run(
440	        run.usage.inputTokens, run.usage.outputTokens, run.usage.cacheReadTokens, run.usage.cacheWriteTokens,
441	        run.costUsd, run.upstreamSeq, run.id,
442	      );
443	      this.db
444	        .prepare(`UPDATE runs SET status = ?, ended_at = ?, duration_ms = ?, error = ? WHERE id = ?`)
445	        .run(status, t, durationMs, status === 'error' ? (run.lastError ?? 'Run failed').slice(0, 2000) : null, run.id);
446	      this.db
447	        .prepare(`UPDATE messages SET content = ?, suggestions = ? WHERE id = ?`)
448	        .run(content, suggestions.length ? JSON.stringify(suggestions) : null, run.assistantMessageId);
449	      this.db.prepare(`UPDATE conversations SET updated_at = ? WHERE id = ?`).run(t, run.conversationId);
450	      this.db.prepare(`UPDATE projects SET last_active_at = ? WHERE id = ?`).run(t, run.projectId);
451	    })();
452	    this.active.delete(run.id);
453	    if (suggestions.length) this.hub.broadcastRun(run.id, { t: 'suggestions', runId: run.id, items: suggestions });
454	    this.hub.broadcastViewers(run.projectId, { t: 'run_status', runId: run.id, conversationId: run.conversationId, projectId: run.projectId, status });
