477	  async abort(runId: string): Promise<boolean> {
478	    const run = this.active.get(runId);
479	    if (!run) {
480	      // orphan (e.g. not driven by this process): mark aborted directly
481	      const r = this.db.prepare(`SELECT status FROM runs WHERE id = ?`).get(runId) as { status: RunStatus } | undefined;
482	      if (r && (r.status === 'running' || r.status === 'queued')) {
483	        this.db.prepare(`UPDATE runs SET status = 'aborted', ended_at = ? WHERE id = ?`).run(now(), runId);
484	        return true;
485	      }
486	      return false;
487	    }
488	    if (run.ended) return false;
489	    run.abortRequested = true;
490	    try {
491	      await this.cb.abort(runId);
492	    } catch (err) {
493	      this.log.warn({ runId, err: (err as Error).message }, 'claudebox abort failed');
494	    }
495	    setTimeout(() => {
496	      if (!run.ended) {
497	        run.controller.abort();
498	        this.synthEnd(run, null);
499	      }
500	    }, ABORT_GRACE_MS).unref();
501	    return true;
502	  }
