506	  /** On startup: re-attach to runs left running by a previous process, or mark them as errored. */
507	  recoverOrphans() {
508	    const rows = this.db
509	      .prepare(
510	        `SELECT r.id, r.conversation_id, r.project_id, r.user_id, r.upstream_seq, r.input_tokens, r.output_tokens, r.cache_read,
511	                r.cache_write, r.cost_usd, r.started_at, m.id AS message_id
512	         FROM runs r LEFT JOIN messages m ON m.run_id = r.id AND m.role = 'assistant'
513	         WHERE r.status IN ('queued','running')`,
514	      )
515	      .all() as {
516	      id: string; conversation_id: string; project_id: string; user_id: string | null; upstream_seq: number;
517	      input_tokens: number; output_tokens: number; cache_read: number; cache_write: number; cost_usd: number;
518	      started_at: number; message_id: string | null;
519	    }[];
520	    for (const r of rows) {
521	      if (this.active.has(r.id)) continue;
522	      const run = this.newState(r.id, r.conversation_id, r.project_id, r.user_id, r.message_id ?? '', null);
523	      run.startedAt = r.started_at;
524	      run.upstreamSeq = r.upstream_seq;
525	      run.usage = { inputTokens: r.input_tokens, outputTokens: r.output_tokens, cacheReadTokens: r.cache_read, cacheWriteTokens: r.cache_write };
526	      run.costUsd = r.cost_usd;
527	      const evs = this.db.prepare(`SELECT seq, type, data FROM run_events WHERE run_id = ? ORDER BY seq`).all(r.id) as {
528	        seq: number; type: string; data: string;
529	      }[];
530	      for (const e of evs) {
531	        run.seq = e.seq;
532	        const d = parseJson<Record<string, unknown>>(e.data, {});
533	        if (e.type === 'text' && typeof d.delta === 'string') {
534	          run.fullText += d.delta;
535	          run.needSep = false;
536	        } else if (e.type === 'block_end' && d.kind === 'text') run.needSep = true;
537	        else if (e.type === 'error') {
538	          run.sawError = true;
539	          run.lastError = String(d.message ?? 'error');
540	        }
541	      }
542	      run.emittedLen = run.fullText.length;
543	      this.active.set(run.id, run);
544	      this.log.info({ runId: r.id }, 'recovering orphaned run');
545	      void this.drive(run, true);
546	    }
547	  }
