727	export function openDb(dbPath: string): DB {
728	  if (dbPath !== ':memory:') fs.mkdirSync(path.dirname(dbPath), { recursive: true });
729	  const db = new Database(dbPath);
730	  db.pragma('journal_mode = WAL');
731	  db.pragma('synchronous = NORMAL');
732	  db.pragma('foreign_keys = ON');
733	  db.pragma('busy_timeout = 5000');
734	  migrate(db);
735	  return db;
736	}
737	
738	function migrate(db: DB) {
739	  const current = db.pragma('user_version', { simple: true }) as number;
740	  for (let v = current; v < MIGRATIONS.length; v++) {
741	    db.transaction(() => {
742	      db.exec(MIGRATIONS[v]!);
743	      db.pragma(`user_version = ${v + 1}`);
744	    })();
745	  }
746	}
