export class Claudebox {
  constructor(private cfg: Config) {}

  private headers(extra: Record<string, string> = {}) {
    return {
      authorization: `Bearer ${this.cfg.claudeboxApiKey}`,
      ...extra,
    };
  }

  /** Start a run; returns the raw undici response (SSE body). */
  startRun(body: V2RunBody, signal: AbortSignal) {
    return request(`${this.cfg.claudeboxUrl}/v2/run`, {
      method: 'POST',
      headers: this.headers({ 'content-type': 'application/json', accept: 'text/event-stream' }),
      body: JSON.stringify(body),
      signal,
      headersTimeout: 60_000,
      bodyTimeout: 0,
    });
  }

  /** Re-attach to a run's buffered event stream. */
  attach(runId: string, fromSeq: number, signal: AbortSignal) {
    return request(`${this.cfg.claudeboxUrl}/v2/run/${encodeURIComponent(runId)}/events?fromSeq=${fromSeq}`, {
      method: 'GET',
      headers: this.headers({ accept: 'text/event-stream' }),
      signal,
      headersTimeout: 30_000,
      bodyTimeout: 0,
    });
  }

  private async json<T>(method: 'GET' | 'POST', path: string, body?: unknown, timeoutMs = 15_000): Promise<T> {
    const res = await request(`${this.cfg.claudeboxUrl}${path}`, {
      method,
      headers: this.headers(body !== undefined ? { 'content-type': 'application/json' } : {}),
      body: body !== undefined ? JSON.stringify(body) : undefined,
      headersTimeout: timeoutMs,
      bodyTimeout: timeoutMs,
    });
    const text = await res.body.text();
    let data: unknown = text;
    try {
      data = JSON.parse(text);
    } catch {
      /* not json */
    }
    if (res.statusCode >= 400) {
      const msg =
        (data as { error?: string | { message?: string } })?.error ?? (typeof data === 'string' ? data : `HTTP ${res.statusCode}`);
      throw new ClaudeboxError(res.statusCode, typeof msg === 'string' ? msg : msg?.message ?? `HTTP ${res.statusCode}`);
    }
    return data as T;
  }

  abort(runId: string) {
    return this.json<unknown>('POST', '/v2/abort', { runId });
  }
  previewStart(projectSlug: string, port: number, command?: string | null) {
    return this.json<PreviewStatusUpstream>('POST', '/v2/preview/start', { projectSlug, port, ...(command ? { command } : {}) }, 60_000);
  }
  previewStop(projectSlug: string, port?: number) {
    return this.json<PreviewStatusUpstream & { stopped?: boolean }>('POST', '/v2/preview/stop', { projectSlug, ...(port ? { port } : {}) });
  }
  previewStatus(projectSlug: string, port?: number) {
    return this.json<PreviewStatusUpstream>(
      'GET',
      `/v2/preview/status?projectSlug=${encodeURIComponent(projectSlug)}${port ? `&port=${port}` : ''}`,
    );
  }
  health() {
    return this.json<Record<string, unknown>>('GET', '/health', undefined, 5000);
  }
}
