const SECRET_KEY = 'claude_auth_token';
const SECRET_UPDATED_KEY = 'claude_auth_token_updated_at';

export class Settings {
  private cache: AppSettings | null = null;
  constructor(private db: DB) {}

  get(): AppSettings {
    if (this.cache) return this.cache;
    const rows = this.db.prepare(`SELECT key, value FROM settings WHERE key NOT IN (?, ?)`).all(SECRET_KEY, SECRET_UPDATED_KEY) as { key: string; value: string }[];
    const s: AppSettings = { ...DEFAULT_SETTINGS };
    for (const r of rows) {
      if (!(r.key in DEFAULT_SETTINGS)) continue;
      try {
        (s as unknown as Record<string, unknown>)[r.key] = JSON.parse(r.value);
      } catch {
        /* ignore corrupt value */
      }
    }
    this.cache = s;
    return s;
  }

  update(patch: Partial<AppSettings>) {
    const stmt = this.db.prepare(`INSERT INTO settings(key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value`);
    this.db.transaction(() => {
      for (const [k, v] of Object.entries(patch)) {
        if (v === undefined || !(k in DEFAULT_SETTINGS)) continue;
        stmt.run(k, JSON.stringify(v));
      }
    })();
    this.cache = null;
  }

  getAuthToken(): string | null {
    const r = this.db.prepare(`SELECT value FROM settings WHERE key = ?`).get(SECRET_KEY) as { value: string } | undefined;
    return r?.value || null;
  }

  setAuthToken(token: string | null) {
    const up = this.db.prepare(`INSERT INTO settings(key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value`);
    this.db.transaction(() => {
      if (!token) this.db.prepare(`DELETE FROM settings WHERE key = ?`).run(SECRET_KEY);
      else up.run(SECRET_KEY, token);
      up.run(SECRET_UPDATED_KEY, String(Date.now()));
    })();
  }

  maskedAuthToken(): { set: boolean; masked: string | null; kind: 'oauth' | 'api_key' | 'unknown' | null; updatedAt: string | null } {
    const t = this.getAuthToken();
    const u = this.db.prepare(`SELECT value FROM settings WHERE key = ?`).get(SECRET_UPDATED_KEY) as { value: string } | undefined;
    const updatedAt = u ? new Date(Number(u.value)).toISOString() : null;
    if (!t) return { set: false, masked: null, kind: null, updatedAt };
    const kind = t.startsWith('sk-ant-api') ? 'api_key' : t.startsWith('sk-ant-oat') ? 'oauth' : 'unknown';
    return { set: true, masked: t.length > 12 ? `${t.slice(0, 7)}…${t.slice(-4)}` : '••••', kind, updatedAt };
  }
}

