export function loadAttachments(db: DB, ids: string[]) {
  if (!ids.length) return [];
  const rows = db.prepare(`SELECT * FROM uploads WHERE id IN (${ids.map(() => '?').join(',')})`).all(...ids) as UploadRow[];
  const byId = new Map(rows.map((r) => [r.id, r]));
  return ids.map((id) => byId.get(id)).filter((r): r is UploadRow => !!r).map(attachmentDTO);
}

