/**
 * Messages with attachments, runs and (for assistant messages) the stored event log.
 * `liveEvents` lets the caller merge not-yet-flushed events for active runs.
 */
export function messagesDTO(db: DB, rows: MessageRow[], replay: (runId: string) => StoredEvent[], withEvents = true) {
  const runIds = [...new Set(rows.map((m) => m.run_id).filter((x): x is string => !!x))];
  const runs = new Map<string, RunRow>();
  if (runIds.length) {
    for (const r of db.prepare(`SELECT * FROM runs WHERE id IN (${runIds.map(() => '?').join(',')})`).all(...runIds) as RunRow[])
      runs.set(r.id, r);
  }
  const userIds = [...new Set(rows.map((m) => m.user_id).filter((x): x is string => !!x))];
  const names = new Map<string, string>();
  if (userIds.length) {
    for (const u of db.prepare(`SELECT id, name FROM users WHERE id IN (${userIds.map(() => '?').join(',')})`).all(...userIds) as {
      id: string;
      name: string;
    }[])
      names.set(u.id, u.name);
  }
  return rows.map((m) => {
    const run = m.run_id ? runs.get(m.run_id) : undefined;
    return {
      id: m.id,
      conversationId: m.conversation_id,
      role: m.role,
      content: m.content,
      attachments: loadAttachments(db, parseJson<string[]>(m.attachments, [])),
      runId: m.run_id,
      createdAt: iso(m.created_at)!,
      ...(m.role === 'user' && m.user_id ? { userName: names.get(m.user_id) ?? 'Unknown' } : {}),
      run: run ? runDTO(run) : null,
      ...(m.role === 'assistant'
        ? {
            events: withEvents && m.run_id ? replay(m.run_id) : [],
            suggestions: parseJson<Suggestion[]>(m.suggestions, []),
          }
        : {}),
    };
  });
}
