export interface ThinkingBlock { kind: 'thinking'; text: string; startedAt?: number; endedAt?: number; done: boolean }
export interface TextBlock { kind: 'text'; text: string; done: boolean }
export interface ToolBlock {
  kind: 'tool'; id: string; name: string; input: any; startedAt?: number; endedAt?: number;
  result?: { isError: boolean; content: string };
}
export type Block = ThinkingBlock | TextBlock | ToolBlock;
export type Todo = { content: string; status: 'pending' | 'in_progress' | 'completed'; activeForm?: string };

export interface RunView {
  runId: string;
  status: RunStatus;
  blocks: Block[];
  todos: Todo[] | null;
  usage: Usage;
  model?: string;
  sessionId?: string;
  result?: { isError: boolean; result: string; durationMs: number; numTurns: number; costUsd: number; usage: Usage };
  error?: string;
  exitCode?: number | null;
  suggestions?: Suggestion[];
  rateLimit?: Record<string, unknown>;
  lastSeq: number;
  startedAt?: number;
  endedAt?: number;
}

export const ZERO_USAGE: Usage = { inputTokens: 0, outputTokens: 0, cacheReadTokens: 0, cacheWriteTokens: 0 };

export function emptyRun(runId: string, status: RunStatus = 'queued', startedAt?: number): RunView {
  return { runId, status, blocks: [], todos: null, usage: { ...ZERO_USAGE }, lastSeq: -1, startedAt };
}

/** Event input: a RunEvent plus optional seq and timestamp (ts in ms; `now` used if absent). */
export type SeqEvent = RunEvent & { seq?: number; ts?: number };

const isTerminal = (s: RunStatus) => s === 'done' || s === 'error' || s === 'aborted';

/**
 * Apply one normalized run event to a RunView and return a NEW RunView (input not mutated).
 * Events with seq <= lastSeq are ignored (dedupe for replay).
 */
export function applyRunEvent(state: RunView, ev: SeqEvent, now: number = Date.now()): RunView {
  if (typeof ev.seq === 'number') {
    if (ev.seq <= state.lastSeq) return state;
  }
  const t = typeof ev.ts === 'number' ? ev.ts : now;
  const s: RunView = { ...state, blocks: state.blocks, lastSeq: typeof ev.seq === 'number' ? ev.seq : state.lastSeq };
  if (s.status === 'queued' && ev.type !== 'done') s.status = 'running';
  if (s.startedAt == null) s.startedAt = t;

  const blocks = () => (s.blocks === state.blocks ? (s.blocks = state.blocks.slice()) : s.blocks);
  const last = () => s.blocks[s.blocks.length - 1];
  const closeOpenThinking = () => {
    const b = last();
    if (b && b.kind === 'thinking' && !b.done) blocks()[s.blocks.length - 1] = { ...b, done: true, endedAt: t };
  };
  const closeOpenText = () => {
    const b = last();
    if (b && b.kind === 'text' && !b.done) blocks()[s.blocks.length - 1] = { ...b, done: true };
  };

  switch (ev.type) {
    case 'init':
      s.model = ev.data.model || s.model;
      s.sessionId = ev.data.sessionId || s.sessionId;
      break;
    case 'thinking': {
      const b = last();
      if (b && b.kind === 'thinking' && !b.done) blocks()[s.blocks.length - 1] = { ...b, text: b.text + (ev.data.delta || '') };
      else { closeOpenText(); blocks().push({ kind: 'thinking', text: ev.data.delta || '', startedAt: t, done: false }); }
      break;
    }
    case 'text': {
      const b = last();
      if (b && b.kind === 'text' && !b.done) blocks()[s.blocks.length - 1] = { ...b, text: b.text + (ev.data.delta || '') };
      else { closeOpenThinking(); blocks().push({ kind: 'text', text: ev.data.delta || '', done: false }); }
      break;
    }
    case 'block_end': {
      // close the most recent open block of that kind
      for (let i = s.blocks.length - 1; i >= 0; i--) {
        const b = s.blocks[i];
        if (b.kind === ev.data.kind && !(b as ThinkingBlock | TextBlock).done) {
          blocks()[i] = b.kind === 'thinking' ? { ...b, done: true, endedAt: t } : { ...(b as TextBlock), done: true };
          break;
        }
      }
      break;
    }
    case 'tool_use': {
      closeOpenThinking(); closeOpenText();
      const idx = s.blocks.findIndex((b) => b.kind === 'tool' && b.id === ev.data.id);
      if (idx >= 0) blocks()[idx] = { ...(s.blocks[idx] as ToolBlock), name: ev.data.name, input: ev.data.input };
      else blocks().push({ kind: 'tool', id: ev.data.id, name: ev.data.name, input: ev.data.input, startedAt: t });
      if (ev.data.name === 'TodoWrite') {
        const todos = (ev.data.input as any)?.todos;
        if (Array.isArray(todos)) s.todos = todos;
      }
      break;
    }
    case 'tool_result': {
      const idx = s.blocks.findIndex((b) => b.kind === 'tool' && b.id === ev.data.id);
      const result = { isError: !!ev.data.isError, content: String(ev.data.content ?? '') };
      if (idx >= 0) blocks()[idx] = { ...(s.blocks[idx] as ToolBlock), result, endedAt: t };
      else blocks().push({ kind: 'tool', id: ev.data.id, name: 'Tool', input: null, result, startedAt: t, endedAt: t });
      break;
    }
    case 'todo':
      s.todos = Array.isArray(ev.data.todos) ? ev.data.todos : s.todos;
      break;
    case 'usage': {
      const u = ev.data;
      s.usage = {
        inputTokens: s.usage.inputTokens + (u.inputTokens || 0),
        outputTokens: s.usage.outputTokens + (u.outputTokens || 0),
        cacheReadTokens: s.usage.cacheReadTokens + (u.cacheReadTokens || 0),
        cacheWriteTokens: s.usage.cacheWriteTokens + (u.cacheWriteTokens || 0),
      };
      break;
    }
    case 'rate_limit':
      s.rateLimit = ev.data;
      break;
    case 'result':
      closeOpenThinking(); closeOpenText();
      s.result = ev.data;
      if (ev.data.usage) s.usage = { ...ZERO_USAGE, ...ev.data.usage };
      if (ev.data.sessionId) s.sessionId = ev.data.sessionId;
      if (ev.data.isError) { s.status = 'error'; if (!s.error && ev.data.result) s.error = ev.data.result; }
      break;
    case 'error':
      s.error = ev.data.message;
      s.status = 'error';
      break;
    case 'done': {
      closeOpenThinking(); closeOpenText();
      s.exitCode = ev.data.exitCode;
      if (!isTerminal(s.status)) {
        if (s.error || s.result?.isError) s.status = 'error';
        else if (ev.data.exitCode != null && ev.data.exitCode !== 0 && !s.result) s.status = 'aborted';
        else s.status = 'done';
      }
      s.endedAt = t;
      // mark any dangling tools as finished (no result)
      s.blocks.forEach((b, i) => { if (b.kind === 'tool' && !b.endedAt) blocks()[i] = { ...b, endedAt: t }; });
      break;
    }
  }
  return s;
}

/** Fold a list of stored events into a RunView. */
export function replay(runId: string, events: SeqEvent[], base?: RunView): RunView {
  let s = base ?? emptyRun(runId, 'running');
  const sorted = events.slice().sort((a, b) => (a.seq ?? 0) - (b.seq ?? 0));
  for (const e of sorted) s = applyRunEvent(s, e, e.ts ?? s.startedAt ?? 0);
  return s;
}

export function setStatus(state: RunView, status: RunStatus, now = Date.now()): RunView {
  if (state.status === status) return state;
  const s = { ...state, status };
  if (isTerminal(status)) {
    s.endedAt = s.endedAt ?? now;
    s.blocks = s.blocks.map((b) => (b.kind !== 'tool' && !b.done ? { ...b, done: true } : b));
  }
  return s;
}

// ---- derived helpers (pure) ----

const SUGG_RE = /<nx-suggestions>[\s\S]*?(<\/nx-suggestions>|$)/g;
/** Strip the suggestions block (even half-streamed) from displayed text. */
export function cleanText(text: string): string {
  let t = text.replace(SUGG_RE, '');
  // partially streamed opening tag at the very end, e.g. "<nx-sugg"
  t = t.replace(/<(n(x(-(s(u(g(g(e(s(t(i(o(n(s)?)?)?)?)?)?)?)?)?)?)?)?)?)?$/, '');
  return t.trimEnd();
}

/** Split blocks into the "process" (everything up to the last tool) and the final answer (trailing text). */
export function splitFinal(blocks: Block[]): { process: Block[]; final: TextBlock[] } {
  let i = blocks.length;
  while (i > 0 && blocks[i - 1].kind !== 'tool') i--;
  // i = index after the last tool. trailing text blocks (ignoring trailing thinking interleaved) form the final answer
  const tail = blocks.slice(i);
  const final = tail.filter((b): b is TextBlock => b.kind === 'text');
  const tailThinking = tail.filter((b) => b.kind === 'thinking');
  return { process: [...blocks.slice(0, i), ...tailThinking], final };
}

export type Segment =
  | { kind: 'thinking'; block: ThinkingBlock; key: string }
  | { kind: 'text'; block: TextBlock; key: string }
  | { kind: 'tools'; tools: ToolBlock[]; key: string };

/** Group consecutive tool blocks into one segment (timeline). */
export function segments(blocks: Block[]): Segment[] {
  const out: Segment[] = [];
  blocks.forEach((b, i) => {
    if (b.kind === 'tool') {
      const prev = out[out.length - 1];
      if (prev && prev.kind === 'tools') prev.tools.push(b);
      else out.push({ kind: 'tools', tools: [b], key: 'g' + b.id });
    } else if (b.kind === 'thinking') out.push({ kind: 'thinking', block: b, key: 't' + i });
    else if (b.text.trim()) out.push({ kind: 'text', block: b, key: 'x' + i });
  });
  return out;
}

/** Count lines added/removed for Edit/Write/MultiEdit inputs (multiset line diff, cheap). */
export function editStats(name: string, input: any): { add: number; del: number } | null {
  if (!input || typeof input !== 'object') return null;
  const lines = (s: unknown) => (typeof s === 'string' && s.length ? s.split('\n') : []);
  const diff = (a: string[], b: string[]) => {
    const m = new Map<string, number>();
    a.forEach((l) => m.set(l, (m.get(l) || 0) + 1));
    let add = 0;
    b.forEach((l) => { const n = m.get(l) || 0; if (n > 0) m.set(l, n - 1); else add++; });
    let del = 0; m.forEach((n) => (del += n));
    return { add, del };
  };
  if (name === 'Write') return { add: lines(input.content).length, del: 0 };
  if (name === 'Edit') return diff(lines(input.old_string), lines(input.new_string));
  if (name === 'MultiEdit' && Array.isArray(input.edits)) {
    return input.edits.reduce((acc: { add: number; del: number }, e: any) => {
      const d = diff(lines(e?.old_string), lines(e?.new_string));
      return { add: acc.add + d.add, del: acc.del + d.del };
    }, { add: 0, del: 0 });
  }
  return null;
}

/** Simple line diff between two texts: returns 1-based line numbers in `next` that are new/changed. */
export function changedLines(prev: string, next: string): number[] {
  const a = prev.split('\n'); const b = next.split('\n');
  // trim common prefix/suffix, then LCS on the middle if small enough, else mark all middle lines
  let start = 0;
  while (start < a.length && start < b.length && a[start] === b[start]) start++;
  let ea = a.length - 1, eb = b.length - 1;
  while (ea >= start && eb >= start && a[ea] === b[eb]) { ea--; eb--; }
  const midA = a.slice(start, ea + 1); const midB = b.slice(start, eb + 1);
  if (midB.length === 0) return [];
  if (midA.length * midB.length > 4_000_000) return midB.map((_, i) => start + i + 1);
  const n = midA.length, m = midB.length;
  const dp: Uint32Array[] = Array.from({ length: n + 1 }, () => new Uint32Array(m + 1));
  for (let i = n - 1; i >= 0; i--) for (let j = m - 1; j >= 0; j--)
    dp[i][j] = midA[i] === midB[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
  const out: number[] = [];
  let i = 0, j = 0;
  while (j < m) {
    if (i < n && midA[i] === midB[j]) { i++; j++; }
    else if (i < n && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else { out.push(start + j + 1); j++; }
  }
  return out;
}

const IRREG: Record<string, string> = {
  run: 'running', set: 'setting', get: 'getting', put: 'putting', stop: 'stopping', plan: 'planning',
  begin: 'beginning', cut: 'cutting', map: 'mapping', wrap: 'wrapping', ship: 'shipping', be: 'being',
  see: 'seeing', go: 'going', do: 'doing', make: 'making', write: 'writing', use: 'using', move: 'moving',
  create: 'creating', update: 'updating', remove: 'removing', save: 'saving', debug: 'debugging', add: 'adding',
  scan: 'scanning', drop: 'dropping', swap: 'swapping', commit: 'committing', configure: 'configuring', try: 'trying',
};
function gerund(v: string): string {
  const w = v.toLowerCase();
  if (IRREG[w]) return IRREG[w];
  if (w.endsWith('ing')) return w;
  if (w.endsWith('ie')) return w.slice(0, -2) + 'ying';
  if (w.endsWith('e') && !w.endsWith('ee')) return w.slice(0, -1) + 'ing';
  return w + 'ing';
}

/**
 * Plain-language one-liner from thinking text: takes the latest complete-ish sentence and
 * rewrites "Let me check X" / "I need to fix X" / "I'll add X" → "Checking X" / "Fixing X" / "Adding X".
 */
export function translateThinking(text: string): string {
  const clean = text.replace(/```[\s\S]*?(```|$)/g, ' ').replace(/[`*_#>]/g, '').replace(/\s+/g, ' ').trim();
  if (!clean) return '';
  const sentences = clean.split(/(?<=[.!?])\s+(?=[A-Z])/).map((s) => s.trim()).filter((s) => s.length > 3);
  // prefer the last sentence that has reasonable length; when streaming the last one may be cut off
  let pick = sentences[sentences.length - 1] || clean;
  // while streaming, the last sentence may be cut off — prefer the last complete one
  if (sentences.length > 1 && (!/[.!?:]$/.test(pick) || pick.length < 12)) pick = sentences[sentences.length - 2];
  let s = pick.replace(/[.!?:;,]+$/, '');
  const m = s.match(/^(?:okay,?\s*|ok,?\s*|so,?\s*|now,?\s*|first,?\s*|next,?\s*|then,?\s*|alright,?\s*)*(?:let me|let's|i'll|i will|i need to|i should|i'm going to|i am going to|i want to|i have to|we need to|i can|time to)\s+([a-z]+)\b(.*)$/i);
  if (m) s = gerund(m[1]) + m[2];
  s = s.replace(/^\s*(the user|user)\s+(wants|is asking|asks)\s+(me\s+)?(to\s+)?/i, 'Understanding the request: ');
  s = s.charAt(0).toUpperCase() + s.slice(1);
  if (s.length > 96) s = s.slice(0, 93).replace(/\s+\S*$/, '') + '…';
  return s;
}
// Run: node --test src/features/workspace/reducer.test.mjs   (Node >= 22.18 strips TS types natively)
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { applyRunEvent, emptyRun, replay, splitFinal, segments, cleanText, editStats, changedLines, translateThinking } from './reducer.ts';

const ev = (seq, type, data, ts) => ({ seq, type, data, ts });

test('streams thinking then text, closing thinking with duration', () => {
  let s = emptyRun('r1', 'queued');
  s = applyRunEvent(s, ev(0, 'init', { sessionId: 'S', model: 'opus', tools: [], cwd: '/w' }), 1000);
  assert.equal(s.status, 'running');
  s = applyRunEvent(s, ev(1, 'thinking', { delta: 'Let me look ' }), 1000);
  s = applyRunEvent(s, ev(2, 'thinking', { delta: 'at the code.' }), 2000);
  s = applyRunEvent(s, ev(3, 'text', { delta: 'Hello' }), 5000);
  s = applyRunEvent(s, ev(4, 'text', { delta: ' world' }), 5100);
  assert.equal(s.blocks.length, 2);
  assert.deepEqual(s.blocks[0], { kind: 'thinking', text: 'Let me look at the code.', startedAt: 1000, endedAt: 5000, done: true });
  assert.equal(s.blocks[1].text, 'Hello world');
  assert.equal(s.blocks[1].done, false);
});

test('dedupes replayed seqs and does not mutate input', () => {
  const a = applyRunEvent(emptyRun('r'), ev(0, 'text', { delta: 'x' }), 0);
  const frozen = JSON.stringify(a);
  const b = applyRunEvent(a, ev(0, 'text', { delta: 'x' }), 0);
  assert.equal(b, a);
  const c = applyRunEvent(a, ev(1, 'text', { delta: 'y' }), 0);
  assert.equal(JSON.stringify(a), frozen);
  assert.equal(c.blocks[0].text, 'xy');
});

test('pairs tool_use with tool_result, todos, usage, result and done', () => {
  const s = replay('r', [
    ev(0, 'text', { delta: 'Working on it.' }),
    ev(1, 'tool_use', { id: 't1', name: 'Read', input: { file_path: '/workspace/projects/a/src/App.tsx' } }),
    ev(2, 'tool_use', { id: 't2', name: 'TodoWrite', input: { todos: [{ content: 'a', status: 'in_progress' }] } }),
    ev(3, 'tool_result', { id: 't1', isError: false, content: 'file body' }),
    ev(4, 'todo', { todos: [{ content: 'a', status: 'completed' }] }),
    ev(5, 'usage', { inputTokens: 10, outputTokens: 5, cacheReadTokens: 0, cacheWriteTokens: 0 }),
    ev(6, 'usage', { inputTokens: 1, outputTokens: 2, cacheReadTokens: 3, cacheWriteTokens: 4 }),
    ev(7, 'text', { delta: 'Done!<nx-suggestions>[{"label":"x"}]</nx-suggestions>' }),
    ev(8, 'result', { sessionId: 'S', isError: false, result: 'Done!', durationMs: 1234, numTurns: 2, costUsd: 0.01, usage: { inputTokens: 11, outputTokens: 7, cacheReadTokens: 3, cacheWriteTokens: 4 } }),
    ev(9, 'done', { exitCode: 0 }),
  ]);
  assert.equal(s.status, 'done');
  const tools = s.blocks.filter((b) => b.kind === 'tool');
  assert.equal(tools.length, 2);
  assert.equal(tools[0].result.content, 'file body');
  assert.deepEqual(s.todos, [{ content: 'a', status: 'completed' }]);
  assert.equal(s.usage.outputTokens, 7);
  const { process, final } = splitFinal(s.blocks);
  assert.equal(final.length, 1);
  assert.equal(cleanText(final[0].text), 'Done!');
  assert.equal(segments(process).length, 2); // interim text + tool group
  assert.ok(s.blocks.every((b) => b.kind === 'tool' || b.done));
});

test('error and abort statuses', () => {
  let s = replay('r', [ev(0, 'error', { message: 'boom' }), ev(1, 'done', { exitCode: 1 })]);
  assert.equal(s.status, 'error');
  assert.equal(s.error, 'boom');
  s = replay('r', [ev(0, 'text', { delta: 'hi' }), ev(1, 'done', { exitCode: 143 })]);
  assert.equal(s.status, 'aborted');
});

test('helpers', () => {
  assert.equal(cleanText('Answer\n<nx-sugg'), 'Answer');
  assert.deepEqual(editStats('Edit', { old_string: 'a\nb', new_string: 'a\nc\nd' }), { add: 2, del: 1 });
  assert.deepEqual(editStats('Write', { content: '1\n2\n3' }), { add: 3, del: 0 });
  assert.deepEqual(changedLines('a\nb\nc', 'a\nB\nc\nd'), [2, 4]);
  assert.equal(translateThinking('The user wants a button. Let me check the config file.'), 'Checking the config file');
  assert.equal(translateThinking("I'll update the router"), 'Updating the router');
});
