175	function ensureSub(runId: string, fromSeq: number) {
176	  if (subscribed.has(runId)) return;
177	  subscribed.add(runId);
178	  live.subRun(runId, fromSeq);
179	}
180	function dropSub(runId: string) {
181	  if (!subscribed.has(runId)) return;
182	  subscribed.delete(runId);
183	  live.unsubRun(runId);
184	}
