186	/** Convert server messages into chat items, synthesizing assistant items for runs that have none yet. */
187	function toItems(msgs: Message[]): ChatItem[] {
188	  const out: ChatItem[] = [];
189	  const assistantRuns = new Set(msgs.filter((m) => m.role === 'assistant' && m.runId).map((m) => m.runId));
190	  for (const m of msgs) {
191	    out.push({
192	      key: m.role === 'assistant' && m.runId ? 'run:' + m.runId : m.id, id: m.id, role: m.role, content: m.content || '',
193	      attachments: m.attachments || [], createdAt: m.createdAt, userName: m.userName, runId: m.runId, run: m.run, suggestions: m.suggestions,
194	    });
195	    if (m.role === 'user' && m.runId && !assistantRuns.has(m.runId)) {
196	      out.push({ key: 'run:' + m.runId, role: 'assistant', content: '', attachments: [], createdAt: m.createdAt, runId: m.runId, run: m.run });
197	    }
198	  }
199	  return out;
200	}
