202	function errInfo(e: unknown): SendError {
203	  if (e instanceof ApiError) {
204	    const limit = e.status === 429 || /limit|quota|budget|exceed/i.test(e.code + ' ' + e.message);
205	    return { code: e.code, message: e.message, status: e.status, limit };
206	  }
207	  return { code: 'error', message: (e as Error)?.message || 'Something went wrong', status: 0 };
208	}
