210	function walkFiles(nodes: FileNode[] | null, fn: (n: FileNode) => void) {
211	  if (!nodes) return;
212	  for (const n of nodes) { fn(n); if (n.children) walkFiles(n.children, fn); }
213	}
214	function findNode(s: { tree: FileNode[] | null; lazyKids: Record<string, FileNode[]> }, path: string): FileNode | null {
215	  let found: FileNode | null = null;
216	  const visit = (n: FileNode) => { if (n.path === path) found = n; };
217	  walkFiles(s.tree, visit);
218	  for (const kids of Object.values(s.lazyKids)) walkFiles(kids, visit);
219	  return found;
220	}
221	export function treeHas(nodes: FileNode[] | null, path: string): boolean {
222	  let found = false; walkFiles(nodes, (n) => { if (n.path === path) found = true; }); return found;
223	}
