240	  const putRun = (runId: string, fn: (r: RunView) => RunView) =>
241	    set((s) => {
242	      const cur = s.runs[runId] ?? emptyRun(runId, 'running');
243	      const next = fn(cur);
244	      return next === cur ? s : { runs: { ...s.runs, [runId]: next } };
245	    });
