257	  const onExternalFileChange = async (path: string, kind: string) => {
258	    const tab = get().tabs.find((t) => t.path === path);
259	    if (!tab || !pid()) return;
260	    if (kind === 'unlink') { patchTab(path, { deleted: true }); return; }
261	    const seq = (fileFetchSeq[path] = (fileFetchSeq[path] || 0) + 1);
262	    try {
263	      const res = await api.get<any>(`/projects/${pid()}/files/content?path=${encodeURIComponent(path)}`);
264	      if (seq !== fileFetchSeq[path] || res?.binary || res?.tooLarge) return;
265	      const content: string = typeof res === 'string' ? res : res?.content ?? '';
266	      const t = get().tabs.find((x) => x.path === path);
267	      if (!t || content === t.saved) { if (t?.deleted) patchTab(path, { deleted: false }); return; }
268	      const dirty = t.content !== t.saved;
269	      if (!dirty) patchTab(path, { content, saved: content, deleted: false, flashAt: Date.now(), flashLines: changedLines(t.saved, content), externalContent: null });
270	      else patchTab(path, { externalContent: content, deleted: false });
271	    } catch { /* ignore */ }
272	  };
