368	    async loadMessages(convId, silent) {
369	      if (!silent) set({ itemsLoading: true });
370	      try {
371	        const msgs = unwrap<Message[]>(await api.get<any>(`/conversations/${convId}/messages`), 'messages', 'items');
372	        if (get().activeConvId !== convId) return;
373	        const items = toItems(msgs);
374	        const runs = { ...get().runs };
375	        for (const m of msgs) {
376	          if (!m.runId || m.role !== 'assistant') continue;
377	          const evs = (m.events || []) as StoredEvent[];
378	          const existing = runs[m.runId];
379	          const maxSeq = evs.reduce((a, e) => Math.max(a, e.seq), -1);
380	          let rv: RunView;
381	          if (existing && existing.lastSeq >= maxSeq) rv = existing;
382	          else {
383	            const startedAt = m.run?.startedAt ? Date.parse(m.run.startedAt) : undefined;
384	            rv = replay(m.runId, evs.map((e) => ({ type: e.type, data: e.data, seq: e.seq, ts: (e as any).ts }) as SeqEvent), emptyRun(m.runId, 'running', startedAt));
385	            if (existing) for (const k of ['suggestions'] as const) if (existing[k] && !rv[k]) rv = { ...rv, [k]: existing[k] };
386	          }
387	          if (m.run) {
388	            if (m.run.status && (terminal(m.run.status) || !terminal(rv.status))) rv = setStatus(rv, m.run.status, m.run.endedAt ? Date.parse(m.run.endedAt) : undefined);
389	            if (m.run.startedAt && !rv.startedAt) rv = { ...rv, startedAt: Date.parse(m.run.startedAt) };
390	            if (m.run.endedAt && terminal(rv.status)) rv = { ...rv, endedAt: Date.parse(m.run.endedAt) };
391	            if (!rv.model && m.run.model) rv = { ...rv, model: m.run.model };
392	          }
393	          if (m.suggestions?.length) rv = { ...rv, suggestions: m.suggestions };
394	          runs[m.runId] = rv;
395	          if (!terminal(rv.status)) ensureSub(m.runId, rv.lastSeq + 1);
396	        }
397	        // user-only run references (assistant not created yet)
398	        for (const it of items) if (it.runId && !runs[it.runId]) {
399	          const st = it.run?.status ?? 'queued';
400	          runs[it.runId] = emptyRun(it.runId, st, it.run?.startedAt ? Date.parse(it.run.startedAt) : undefined);
401	          if (!terminal(st)) ensureSub(it.runId, 0);
402	        }
403	        set({ items, runs, itemsLoading: false });
404	      } catch (e) {
405	        set({ itemsLoading: false });
406	        if (!silent) set({ sendError: errInfo(e) });
407	      }
408	    },
