410	    async send(text) {
411	      const s = get();
412	      const project = s.project;
413	      if (!project || !s.canEdit || s.sending) return false;
414	      const ups = s.uploads;
415	      if (ups.some((u) => u.status === 'uploading')) { set({ sendError: { code: 'uploading', message: 'Wait for uploads to finish.', status: 0 } }); return false; }
416	      const att = ups.filter((u) => u.status === 'done' && u.result);
417	      if (!text.trim() && !att.length) return false;
418	      set({ sending: true, sendError: null });
419	      try {
420	        let convId = s.activeConvId;
421	        if (!convId) {
422	          const title = text.trim().split('\n')[0].slice(0, 60) || 'New conversation';
423	          const conv = unwrap<Conversation>(await api.post<any>(`/projects/${project.id}/conversations`, { title, model: s.prefs.model, mode: s.prefs.mode }), 'conversation');
424	          convId = conv.id;
425	          set((st) => ({ conversations: [conv, ...st.conversations.filter((c) => c.id !== conv.id)], activeConvId: conv.id, items: [] }));
426	          try { localStorage.setItem(`nx:ws:conv:${project.id}`, conv.id); } catch { /* */ }
427	        }
428	        const { prefs } = get();
429	        const body = { text, attachments: att.map((u) => u.result!.id), model: prefs.model, mode: prefs.mode, thinking: prefs.thinking };
430	        const res = await api.post<{ runId: string; messageId: string }>(`/conversations/${convId}/prompt`, body);
431	        const now = new Date().toISOString();
432	        const runId = res.runId;
433	        set((st) => ({
434	          items: [
435	            ...st.items,
436	            { key: res.messageId || 'local:' + runId, id: res.messageId, role: 'user', content: text, attachments: att.map((u) => u.result!), createdAt: now, runId },
437	            { key: 'run:' + runId, role: 'assistant', content: '', attachments: [], createdAt: now, runId,
438	              run: { id: runId, status: 'queued', model: prefs.model, mode: prefs.mode, startedAt: now, inputTokens: 0, outputTokens: 0, cacheRead: 0, cacheWrite: 0, costUsd: 0 } },
439	          ],
440	          runs: { ...st.runs, [runId]: st.runs[runId] ?? emptyRun(runId, 'queued', Date.now()) },
441	          uploads: [], sending: false,
442	        }));
443	        att.forEach((u) => u.previewUrl && URL.revokeObjectURL(u.previewUrl));
444	        ensureSub(runId, 0);
445	        return true;
446	      } catch (e) {
447	        set({ sending: false, sendError: errInfo(e) });
448	        return false;
449	      }
450	    },
