465	    handleServerMsg(msg) {
466	      const s = get();
467	      // Claude often starts dev servers itself via Bash; recheck the preview once commands settle.
468	      const schedulePreviewCheck = () => {
469	        window.clearTimeout(previewCheckTimer);
470	        previewCheckTimer = window.setTimeout(() => get().refreshPreview(), 1200);
471	      };
472	      switch (msg.t) {
473	        case 'run_event': {
474	          if (!subscribed.has(msg.runId) && !s.runs[msg.runId]) return;
475	          const { t: _t, runId, ...ev } = msg as any;
476	          putRun(msg.runId, (r) => applyRunEvent(r, ev as SeqEvent));
477	          if (msg.type === 'done') { dropSub(msg.runId); scheduleReconcile(); }
478	          if (msg.type === 'tool_result' || msg.type === 'done') schedulePreviewCheck();
479	          break;
480	        }
481	        case 'run_status': {
482	          if (s.runs[msg.runId]) {
483	            putRun(msg.runId, (r) => (terminal(r.status) && !terminal(msg.status) ? r : setStatus(r, msg.status)));
484	            if (terminal(msg.status)) { dropSub(msg.runId); scheduleReconcile(); }
485	          } else if (msg.conversationId && msg.conversationId === s.activeConvId) {
486	            scheduleReconcile();
487	          } else if (msg.projectId === s.project?.id) {
488	            window.clearTimeout(reconcileTimer);
489	            reconcileTimer = window.setTimeout(() => get().loadConversations(), 500);
490	          }
491	          break;
492	        }
493	        case 'suggestions': {
494	          set((st) => ({ liveSuggestions: { ...st.liveSuggestions, [msg.runId]: msg.items } }));
495	          if (s.runs[msg.runId]) putRun(msg.runId, (r) => ({ ...r, suggestions: msg.items }));
496	          break;
497	        }
498	        case 'file_change': {
499	          if (msg.projectId !== s.project?.id) return;
500	          const path = msg.path.replace(/^\.?\//, '');
501	          if (msg.kind === 'add' || msg.kind === 'change' || msg.kind === 'addDir') {
502	            set((st) => ({ flashes: { ...st.flashes, [path]: Date.now() } }));
503	            window.setTimeout(() => set((st) => {
504	              const f = { ...st.flashes }; if (f[path] && Date.now() - f[path] >= 1900) delete f[path]; return { flashes: f };
505	            }), 2000);
506	          }
507	          set({ lastFileChangeAt: Date.now() });
508	          window.clearTimeout(treeTimer);
509	          treeTimer = window.setTimeout(() => get().refreshTree(), 250);
510	          if (msg.kind === 'change' || msg.kind === 'add' || msg.kind === 'unlink') onExternalFileChange(path, msg.kind);
511	          const pp = get().previewPrefs;
512	          if (pp.autoRefresh && !pp.hmr && get().preview?.running) {
513	            window.clearTimeout(previewTimer);
514	            previewTimer = window.setTimeout(() => get().reloadPreview(), 600);
515	          }
516	          break;
517	        }
518	        case 'preview_status': {
519	          if (msg.projectId !== s.project?.id) return;
520	          set((st) => ({ preview: { ...(st.preview ?? { url: `/preview/${st.project!.slug}/` }), running: msg.running, port: msg.port } as PreviewStatus }));
521	          break;
522	        }
523	      }
524	    },
