534	    addFiles(files) {
535	      const project = get().project;
536	      if (!project || !get().canEdit) return;
537	      for (const file of files) {
538	        const localId = Math.random().toString(36).slice(2);
539	        const isImg = file.type.startsWith('image/');
540	        const up: PendingUpload = {
541	          localId, file, name: file.name || 'pasted-file', size: file.size, mime: file.type, progress: 0, status: 'uploading',
542	          previewUrl: isImg ? URL.createObjectURL(file) : undefined,
543	        };
544	        set((s) => ({ uploads: [...s.uploads, up] }));
545	        const form = new FormData();
546	        form.append('projectId', project.id);
547	        form.append('file', file, up.name);
548	        const patch = (p: Partial<PendingUpload>) => set((s) => ({ uploads: s.uploads.map((u) => (u.localId === localId ? { ...u, ...p } : u)) }));
549	        api.upload<Attachment>('/uploads', form, (f) => patch({ progress: f }))
550	          .then((r) => patch({ status: 'done', progress: 1, result: unwrap<Attachment>(r, 'upload') }))
551	          .catch((e) => patch({ status: 'error', error: errInfo(e).message }));
552	      }
