export function PromptBox() {
  const prefs = useWs((s) => s.prefs);
  const setPrefs = useWs((s) => s.setPrefs);
  // per-user mode restrictions (admin limits); the server enforces them, the UI just hides what would be refused
  const allowedModes = useAuth((s) => s.user?.limits?.modes);
  const modes = useMemo(() => (allowedModes?.length ? MODES.filter((m) => allowedModes.includes(m.id)) : MODES), [allowedModes]);
  useEffect(() => { if (modes.length && !modes.some((m) => m.id === prefs.mode)) setPrefs({ mode: modes[0].id }); }, [modes, prefs.mode, setPrefs]);
  const models = useWs((s) => s.models);
  const canEdit = useWs((s) => s.canEdit);
  const uploads = useWs((s) => s.uploads);
  const draft = useWs((s) => s.draft);
  const sending = useWs((s) => s.sending);
  const sendError = useWs((s) => s.sendError);
  const items = useWs((s) => s.items);
  const runs = useWs((s) => s.runs);
  const usage = useWs((s) => s.usage);
  const { send, abort, addFiles, removeUpload, newConversation, clearSendError, setRightTab, set } = useWs.getState();

  const [text, setText] = useState('');
  const [focused, setFocused] = useState(false);
  const [menu, setMenu] = useState<null | 'mode' | 'model' | 'thinking'>(null);
  const [modeEl, setModeEl] = useState<HTMLElement | null>(null);
  const [modelEl, setModelEl] = useState<HTMLElement | null>(null);
  const [thinkEl, setThinkEl] = useState<HTMLElement | null>(null);
  const [micErr, setMicErr] = useState<string | null>(null);
  const [slashIdx, setSlashIdx] = useState(0);
  const [slashDismissed, setSlashDismissed] = useState(false);
  const ta = useRef<HTMLTextAreaElement>(null);
  const fileInput = useRef<HTMLInputElement>(null);

  const runningId = useMemo(() => {
    for (let i = items.length - 1; i >= 0; i--) { const r = items[i].runId && runs[items[i].runId!]; if (r && !isTerminal(r.status)) return r.runId; }
    return null;
  }, [items, runs]);

  // draft injections (suggestion alt-click, etc.)
  useEffect(() => {
    if (!draft.nonce) return;
    setText(draft.text);
    requestAnimationFrame(() => { const el = ta.current; if (el) { el.focus(); el.setSelectionRange(el.value.length, el.value.length); } });
  }, [draft.nonce]); // eslint-disable-line react-hooks/exhaustive-deps

  // focus shortcut from elsewhere
  useEffect(() => {
    const f = () => ta.current?.focus();
    window.addEventListener('nxw:focus-prompt', f);
    return () => window.removeEventListener('nxw:focus-prompt', f);
  }, []);

  // autosize
  useLayoutEffect(() => {
    const el = ta.current; if (!el) return;
    el.style.height = '0px';
    el.style.height = Math.min(el.scrollHeight, Math.round(window.innerHeight * 0.4)) + 'px';
  }, [text]);

  const insertAtCursor = useCallback((t: string) => {
    const el = ta.current;
    setText((cur) => {
      const s = el?.selectionStart ?? cur.length, e = el?.selectionEnd ?? cur.length;
      const pre = cur.slice(0, s), post = cur.slice(e);
      const sep = pre && !/\s$/.test(pre) ? ' ' : '';
      const next = pre + sep + t + (post && !/^\s/.test(post) ? ' ' : '') + post;
      requestAnimationFrame(() => { if (el) { const p = (pre + sep + t).length; el.focus(); el.setSelectionRange(p, p); } });
      return next;
    });
  }, []);

  // ---- slash commands ----
  const slash = useMemo(() => {
    if (slashDismissed || !text.startsWith('/')) return null;
    const m1 = /^\/(\w*)$/.exec(text);
    if (m1) {
      const q = m1[1].toLowerCase();
      const list = COMMANDS.filter((c) => c.name.startsWith(q));
      return list.length ? { kind: 'cmd' as const, list: list.map((c) => ({ key: c.name, label: '/' + c.name, hint: c.args, desc: c.desc, apply: c.args ? '/' + c.name + ' ' : '/' + c.name })) } : null;
    }
    const m2 = /^\/(model|mode)\s+(\S*)$/i.exec(text);
    if (m2) {
      const q = m2[2].toLowerCase();
      const opts = m2[1].toLowerCase() === 'model'
        ? models.map((m) => ({ key: m.id, label: m.label, desc: m.id }))
        : modes.map((m) => ({ key: m.id, label: m.label, desc: m.desc }));
      const list = opts.filter((o) => o.key.toLowerCase().startsWith(q) || o.label.toLowerCase().startsWith(q));
      return list.length ? { kind: 'arg' as const, list: list.map((o) => ({ ...o, hint: undefined, apply: `/${m2[1].toLowerCase()} ${o.key}` })) } : null;
    }
    return null;
  }, [text, models, modes, slashDismissed]);
  useEffect(() => { setSlashIdx(0); }, [slash?.list.length, slash?.kind]);
  useEffect(() => { if (!text.startsWith('/')) setSlashDismissed(false); }, [text]);

  const runCommand = (raw: string): boolean => {
    const m = /^\/(\w+)(?:\s+(.*))?$/.exec(raw.trim());
    if (!m) return false;
    const [, name, arg = ''] = m;
    const a = arg.trim().toLowerCase();
    switch (name.toLowerCase()) {
      case 'new': case 'clear': newConversation(); setText(''); return true;
      case 'preview': setRightTab('preview', true); set('mobileTab', 'preview'); setText(''); return true;
      case 'files': set('leftTab', 'files'); set('leftCollapsed', false); set('mobileTab', 'files'); setText(''); return true;
      case 'model': {
        const mm = models.find((x) => x.id.toLowerCase() === a || x.label.toLowerCase().includes(a));
        if (mm || a) { setPrefs({ model: mm?.id ?? arg.trim() }); setText(''); return true; }
        return false;
      }
      case 'mode': {
        const md = modes.find((x) => x.id === a);
        if (md) { setPrefs({ mode: md.id }); setText(''); return true; }
        return false;
      }
    }
    return false;
  };

  const doSend = async () => {
    if (!canEdit || sending) return;
    const t = text;
    if (t.startsWith('/') && runCommand(t)) return;
    if (runningId) return;
    if (!t.trim() && !uploads.some((u) => u.status === 'done')) return;
    const ok = await send(t);
    if (ok) setText('');
  };

  const onKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (slash) {
      if (e.key === 'ArrowDown') { e.preventDefault(); setSlashIdx((i) => (i + 1) % slash.list.length); return; }
      if (e.key === 'ArrowUp') { e.preventDefault(); setSlashIdx((i) => (i - 1 + slash.list.length) % slash.list.length); return; }
      if (e.key === 'Escape') { e.preventDefault(); setSlashDismissed(true); return; }
      if (e.key === 'Tab' || (e.key === 'Enter' && !e.shiftKey)) {
        const it = slash.list[slashIdx];
        if (it) {
          e.preventDefault();
          const full = it.apply;
          if (e.key === 'Enter' && (slash.kind === 'arg' || !full.endsWith(' '))) { if (!runCommand(full)) setText(full); }
          else setText(full);
          return;
        }
      }
    }
    if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) { e.preventDefault(); doSend(); }
  };

  const onPaste = (e: React.ClipboardEvent) => {
    const files = Array.from(e.clipboardData.files || []);
    if (files.length) { e.preventDefault(); addFiles(files.map((f, i) => (f.name && f.name !== 'image.png') ? f : new File([f], `pasted-${Date.now()}-${i}.${(f.type.split('/')[1] || 'bin').replace('jpeg', 'jpg')}`, { type: f.type }))); }
  };

  const mode = MODES.find((m) => m.id === prefs.mode) ?? MODES[0];
  const model = models.find((m) => m.id === prefs.model);
  const think = THINKING.find((t) => t.id === prefs.thinking) ?? THINKING[1];
  const hasContent = !!text.trim() || uploads.some((u) => u.status === 'done');
  const limitPct = usage?.limits?.dailyTokens ? Math.min(1, ((usage.today.inputTokens || 0) + (usage.today.outputTokens || 0)) / usage.limits.dailyTokens) : null;

  if (!canEdit) {
    return (
      <div className="border-t border-line/60 px-4 py-3">
        <div className="mx-auto flex max-w-[820px] items-center justify-center gap-2 rounded-xl border border-dashed border-line px-4 py-3 text-[13px] text-muted">
          <Eye size={15} /> You have view-only access to this project.
        </div>
      </div>
    );
  }

  return (
    <div className="relative px-3 pb-3 pt-1 sm:px-5">
      <div className="mx-auto max-w-[820px]">
        {sendError && (
          <div className={clsx('nxw-fade-in mb-2 flex items-start gap-2 rounded-xl border px-3 py-2 text-[13px]',
            sendError.limit ? 'border-warn/40 bg-warn/[.07] text-warn' : 'border-bad/40 bg-bad/[.07] text-bad')}>
            {sendError.limit ? <Gauge size={15} className="mt-0.5 shrink-0" /> : <TriangleAlert size={15} className="mt-0.5 shrink-0" />}
            <div className="min-w-0 flex-1">
              {sendError.limit && <div className="font-medium">{/token_limit$/.test(sendError.code) ? 'Usage limit reached' : 'Not allowed'}</div>}
              <div className={clsx(sendError.limit && 'text-warn/80')}>{sendError.limit ? `${sendError.message.replace(/\.?$/, '.')} Contact an admin ${/token_limit$/.test(sendError.code) ? 'to raise it' : 'to change your access'}.` : sendError.message}</div>
            </div>
            <button type="button" onClick={clearSendError} className="shrink-0 opacity-70 hover:opacity-100"><X size={14} /></button>
          </div>
        )}
        {micErr && (
          <div className="nxw-fade-in mb-2 flex items-center gap-2 rounded-xl border border-warn/30 bg-warn/[.06] px-3 py-1.5 text-[12.5px] text-warn">
            <TriangleAlert size={14} /> <span className="flex-1">{micErr}</span>
            <button type="button" onClick={() => setMicErr(null)}><X size={13} /></button>
          </div>
        )}

        <div className={clsx(
          'nxw-prompt relative rounded-2xl border bg-panel/90 backdrop-blur transition-all duration-200',
          focused ? 'border-pink/50 shadow-[0_0_0_3px_rgba(255,62,138,.10),0_0_40px_-12px_rgba(255,62,138,.55)]' : 'border-line shadow-[0_10px_40px_-20px_rgba(0,0,0,.9)]',
        )}>
          {/* slash popup */}
          {slash && focused && (
            <div className="nxw-pop absolute bottom-full left-2 z-20 mb-2 w-[min(380px,calc(100%-16px))] overflow-hidden rounded-xl border border-line bg-panel/95 p-1 shadow-[0_18px_50px_rgba(0,0,0,.7)] backdrop-blur-md">
              <div className="px-2.5 pb-1 pt-1.5 text-[10.5px] uppercase tracking-[.14em] text-muted">{slash.kind === 'cmd' ? 'Commands' : 'Options'}</div>
              {slash.list.map((it, i) => (
                <button key={it.key} type="button" onMouseDown={(e) => { e.preventDefault(); if (!it.apply.endsWith(' ') && runCommand(it.apply)) return; setText(it.apply); ta.current?.focus(); }}
                  onMouseEnter={() => setSlashIdx(i)}
                  className={clsx('flex w-full items-baseline gap-2 rounded-lg px-2.5 py-1.5 text-left text-[13px]', i === slashIdx ? 'bg-pink/10 text-ink' : 'text-ink/80')}>
                  <span className={clsx('font-mono', i === slashIdx && 'text-hot')}>{it.label}</span>
                  {it.hint && <span className="font-mono text-[11px] text-muted">{it.hint}</span>}
                  <span className="ml-auto truncate text-[12px] text-muted">{it.desc}</span>
                </button>
              ))}
            </div>
          )}

          {/* attachments */}
          {uploads.length > 0 && (
            <div className="flex flex-wrap gap-2 px-3 pt-3">
              {uploads.map((u) => (
                <div key={u.localId} className={clsx('nxw-fade-in group relative overflow-hidden rounded-lg border bg-bg/60', u.status === 'error' ? 'border-bad/50' : 'border-line')}>
