                </Tip>
              )}
              {runningId ? (
                <Tip label="Stop" kbd={`${modKey}.`}>
                  <button type="button" onClick={() => abort(runningId)}
                    className="flex h-8 w-8 items-center justify-center rounded-full border border-pink/50 bg-pink/10 text-hot transition hover:bg-pink/20 nxw-ring">
                    <Square size={11} fill="currentColor" />
                  </button>
                </Tip>
              ) : (
                <Tip label="Send" kbd="↵">
                  <button type="button" onClick={doSend} disabled={!hasContent || sending}
                    className={clsx('flex h-8 w-8 items-center justify-center rounded-full transition-all duration-200',
                      hasContent ? 'bg-gradient-to-br from-pink to-hot text-black shadow-[0_0_20px_-2px_rgba(255,62,138,.8)] hover:scale-105' : 'bg-white/[.06] text-muted')}>
                    {sending ? <span className="h-3.5 w-3.5 animate-spin rounded-full border-2 border-black/30 border-t-black" /> : <ArrowUp size={16} strokeWidth={2.5} />}
                  </button>
                </Tip>
              )}
            </div>
          </div>
        </div>
      </div>

      <Popover open={menu === 'mode'} anchor={modeEl} onClose={() => setMenu(null)} className="w-[300px]">
        {modes.map((m) => (
          <button key={m.id} type="button" onClick={() => { setPrefs({ mode: m.id }); setMenu(null); }}
            className={clsx('flex w-full items-start gap-2.5 rounded-lg px-2.5 py-2 text-left transition-colors', prefs.mode === m.id ? 'bg-pink/10' : 'hover:bg-white/5')}>
            <m.icon size={15} className={clsx('mt-0.5 shrink-0', prefs.mode === m.id ? 'text-hot' : 'text-muted')} />
            <span className="min-w-0 flex-1">
              <span className="block text-[13px] text-ink">{m.label}</span>
              <span className="block text-[11.5px] leading-snug text-muted">{m.desc}</span>
            </span>
            {prefs.mode === m.id && <Check size={14} className="mt-0.5 text-hot" />}
          </button>
        ))}
      </Popover>
      <Popover open={menu === 'model'} anchor={modelEl} onClose={() => setMenu(null)} className="w-[220px]">
        {(models.length ? models : [{ id: prefs.model, label: prefs.model }]).map((m) => (
          <MenuItem key={m.id} active={prefs.model === m.id} icon={<Cpu size={14} />} hint={prefs.model === m.id ? <Check size={13} /> : undefined}
            onClick={() => { setPrefs({ model: m.id }); setMenu(null); }}>
