          </MenuItem>
        ))}
      </Popover>
      <Popover open={menu === 'thinking'} anchor={thinkEl} onClose={() => setMenu(null)} className="w-[250px]">
        <div className="px-2.5 pb-1 pt-1.5 text-[10.5px] uppercase tracking-[.14em] text-muted">Extended thinking</div>
        {THINKING.map((t) => (
          <button key={t.id} type="button" onClick={() => { setPrefs({ thinking: t.id }); setMenu(null); }}
            className={clsx('flex w-full items-start gap-2.5 rounded-lg px-2.5 py-1.5 text-left', prefs.thinking === t.id ? 'bg-pink/10' : 'hover:bg-white/5')}>
            <Brain size={14} className={clsx('mt-0.5', prefs.thinking === t.id ? 'text-hot' : 'text-muted')} />
            <span className="flex-1"><span className="block text-[13px] text-ink">{t.label}</span><span className="block text-[11.5px] text-muted">{t.desc}</span></span>
            {prefs.thinking === t.id && <Check size={14} className="mt-0.5 text-hot" />}
          </button>
        ))}
      </Popover>
    </div>
  );
}
