export function Chat() {
  const items = useWs((s) => s.items);
  const runs = useWs((s) => s.runs);
  const itemsLoading = useWs((s) => s.itemsLoading);
  const canEdit = useWs((s) => s.canEdit);
  const retry = useWs((s) => s.retry);
  const activeConvId = useWs((s) => s.activeConvId);
  const scroller = useRef<HTMLDivElement>(null);
  const content = useRef<HTMLDivElement>(null);
  const stick = useRef(true);
  const [showJump, setShowJump] = useState(false);

  const toBottom = useCallback((smooth = false) => {
    const el = scroller.current; if (!el) return;
    el.scrollTo({ top: el.scrollHeight, behavior: smooth ? 'smooth' : 'auto' });
  }, []);

  const onScroll = () => {
    const el = scroller.current; if (!el) return;
    const dist = el.scrollHeight - el.scrollTop - el.clientHeight;
    stick.current = dist < 80;
    setShowJump(dist > 240);
  };

  // stick to bottom when content grows (streaming)
  useEffect(() => {
    const el = content.current; if (!el) return;
    const ro = new ResizeObserver(() => { if (stick.current) toBottom(); });
    ro.observe(el);
    return () => ro.disconnect();
  }, [toBottom]);

  // new conversation / new messages from the user → jump to bottom
  const lastKey = items[items.length - 1]?.key;
  const lastUser = [...items].reverse().find((i) => i.role === 'user')?.key;
  useLayoutEffect(() => { stick.current = true; toBottom(); }, [activeConvId, lastUser, toBottom]);
  useEffect(() => { if (stick.current) toBottom(); }, [lastKey, toBottom]);

  const lastAssistant = [...items].reverse().find((i) => i.role === 'assistant')?.key;

  return (
    <div className="relative flex h-full min-h-0 flex-col">
      <div className="relative min-h-0 flex-1">
      <div ref={scroller} onScroll={onScroll} className="nxw-scroll absolute inset-0 overflow-y-auto">
        <div ref={content} className="mx-auto w-full max-w-[820px] px-4 pb-6 pt-6 sm:px-6">
          {itemsLoading && !items.length ? (
            <div className="flex justify-center py-20"><Spin /></div>
          ) : !items.length ? (
            <div className="h-[calc(100vh-280px)] min-h-[360px]"><EmptyChat /></div>
          ) : (
            <div className="space-y-7">
              {items.map((it) => it.role === 'user' ? <UserBubble key={it.key} item={it} /> : (
                <AssistantMessage
                  key={it.key} run={it.runId ? runs[it.runId] : undefined} fallbackText={it.content} model={it.run?.model}
                  suggestions={it.suggestions} isLast={it.key === lastAssistant} canEdit={canEdit}
                  onRetry={it.runId ? () => retry(it.runId!) : undefined}
                />
              ))}
            </div>
          )}
        </div>
      </div>
      <button
        type="button" onClick={() => { stick.current = true; toBottom(true); }}
        className={clsx(
          'absolute bottom-3 left-1/2 z-10 -translate-x-1/2 transition-all duration-200',
          'inline-flex items-center gap-1.5 rounded-full border border-pink/40 bg-panel/90 px-3 py-1 text-xs text-ink shadow-[0_0_20px_-4px_rgba(255,62,138,.6)] backdrop-blur',
          showJump ? 'pointer-events-auto translate-y-0 opacity-100' : 'pointer-events-none translate-y-2 opacity-0',
        )}
      >
        <ArrowDown size={12} /> Jump to latest
      </button>
      </div>
      <PromptBox />
    </div>
  );
}

