// ---------- Tooltip ----------
export function Tip({ label, children, side = 'top', kbd }: { label: ReactNode; children: ReactElement<any>; side?: 'top' | 'bottom' | 'left' | 'right'; kbd?: string }) {
  const [rect, setRect] = useState<DOMRect | null>(null);
  const timer = useRef<number>();
  const show = (e: React.SyntheticEvent) => {
    const el = e.currentTarget as HTMLElement;
    window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => setRect(el.getBoundingClientRect()), 350);
  };
  const hide = () => { window.clearTimeout(timer.current); setRect(null); };
  useEffect(() => () => window.clearTimeout(timer.current), []);
  const child = cloneElement(children, {
    onMouseEnter: (e: any) => { show(e); children.props.onMouseEnter?.(e); },
    onMouseLeave: (e: any) => { hide(); children.props.onMouseLeave?.(e); },
    onMouseDown: (e: any) => { hide(); children.props.onMouseDown?.(e); },
    onFocus: (e: any) => { children.props.onFocus?.(e); },
    onBlur: (e: any) => { hide(); children.props.onBlur?.(e); },
  });
  let style: React.CSSProperties = {};
  if (rect) {
    const cx = rect.left + rect.width / 2, cy = rect.top + rect.height / 2;
    if (side === 'top') style = { left: cx, top: rect.top - 8, transform: 'translate(-50%, -100%)' };
    if (side === 'bottom') style = { left: cx, top: rect.bottom + 8, transform: 'translate(-50%, 0)' };
    if (side === 'left') style = { left: rect.left - 8, top: cy, transform: 'translate(-100%, -50%)' };
    if (side === 'right') style = { left: rect.right + 8, top: cy, transform: 'translate(0, -50%)' };
  }
  return (
    <>
      {child}
      {rect && createPortal(
        <div className="nxw-tip pointer-events-none fixed z-[1000] max-w-[280px] rounded-md border border-line bg-panel2/95 px-2.5 py-1.5 text-xs text-ink shadow-[0_8px_30px_rgba(0,0,0,.6)] backdrop-blur" style={style}>
          {label}
          {kbd && <span className="ml-2 rounded border border-line px-1 font-mono text-[10px] text-muted">{kbd}</span>}
        </div>,
        document.body,
      )}
    </>
  );
}

// ---------- Popover ----------
export function Popover({
  open, onClose, anchor, children, side = 'top', align = 'start', className,
}: {
  open: boolean; onClose: () => void; anchor: HTMLElement | null; children: ReactNode;
  side?: 'top' | 'bottom'; align?: 'start' | 'end'; className?: string;
}) {
  const ref = useRef<HTMLDivElement>(null);
  const [pos, setPos] = useState<React.CSSProperties>({ visibility: 'hidden' });
  useLayoutEffect(() => {
    if (!open || !anchor) return;
    const place = () => {
      const r = anchor.getBoundingClientRect();
      const el = ref.current; const w = el?.offsetWidth ?? 220; const h = el?.offsetHeight ?? 0;
      let left = align === 'start' ? r.left : r.right - w;
      left = Math.max(8, Math.min(left, window.innerWidth - w - 8));
      let top = side === 'top' ? r.top - h - 6 : r.bottom + 6;
      if (side === 'top' && top < 8) top = r.bottom + 6;
      if (side === 'bottom' && top + h > window.innerHeight - 8) top = Math.max(8, r.top - h - 6);
      setPos({ left, top });
    };
    place();
    const ro = new ResizeObserver(place); if (ref.current) ro.observe(ref.current);
    window.addEventListener('resize', place);
    return () => { ro.disconnect(); window.removeEventListener('resize', place); };
  }, [open, anchor, side, align]);
  useEffect(() => {
    if (!open) return;
    const onDown = (e: MouseEvent) => {
      if (ref.current?.contains(e.target as Node) || anchor?.contains(e.target as Node)) return;
      onClose();
    };
    const onKey = (e: KeyboardEvent) => { if (e.key === 'Escape') { e.stopPropagation(); onClose(); } };
    document.addEventListener('mousedown', onDown);
    document.addEventListener('keydown', onKey, true);

