export interface AdminSettings {
  models: ModelInfo[]; defaultModel: string; globalDailyTokenCap: number | null;
  claudeAuth: { set: boolean; masked: string | null; kind?: 'oauth' | 'apiKey' | string | null; updatedAt?: string | null };
