export async function getSettings(): Promise<AdminSettings> {
  const r = await api.get<any>('/admin/settings');
  const s = r?.settings ?? r ?? {};
  const ca = s.claudeAuth ?? s.claudeAuthToken ?? {};
  return {
    models: arr(s.models),
    defaultModel: s.defaultModel ?? s.default_model ?? '',
    globalDailyTokenCap: s.globalDailyTokenCap ?? s.global_daily_token_cap ?? null,
    claudeAuth: typeof ca === 'string'
