  };
}
/** Only send what changed. claudeAuthToken is write-only (empty string clears it). */
export const saveSettings = (patch: Partial<Omit<AdminSettings, 'claudeAuth'>> & { claudeAuthToken?: string }) => api.put('/admin/settings', patch);
import { useEffect, useRef, type ReactNode } from 'react';
import { createPortal } from 'react-dom';
import { X } from 'lucide-react';
import { cn } from './cn';

/**
 * Modal — centered dialog in a portal, Esc / backdrop click closes, focus moves inside.
 *  open, onClose, title?, description?, children, footer? (right-aligned action row)
 *  size 'sm'(380) | 'md'(520) | 'lg'(720) | 'xl'(960)  (default 'md'); dismissible (default true)
 * Drawer — side sheet, same props + side 'right'|'left' (default right), width px (default 560).
 */
export interface ModalProps {
  open: boolean; onClose: () => void; title?: ReactNode; description?: ReactNode; children?: ReactNode; footer?: ReactNode;
  size?: 'sm' | 'md' | 'lg' | 'xl'; dismissible?: boolean; className?: string; icon?: ReactNode;
}
const msz = { sm: 'max-w-[380px]', md: 'max-w-[520px]', lg: 'max-w-[720px]', xl: 'max-w-[960px]' };

function useDialog(open: boolean, onClose: () => void, dismissible: boolean) {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!open) return;
    const prev = document.activeElement as HTMLElement | null;
    const t = window.setTimeout(() => {
      const el = ref.current;
      if (!el) return;
      const f = el.querySelector<HTMLElement>('[autofocus],input:not([disabled]):not([type=hidden]),textarea:not([disabled]),select:not([disabled])');
      (f || el).focus();
    }, 20);
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && dismissible) { e.stopPropagation(); onClose(); }
      if (e.key === 'Tab' && ref.current) {
        const els = Array.from(ref.current.querySelectorAll<HTMLElement>('a[href],button:not([disabled]),input:not([disabled]),select,textarea,[tabindex]:not([tabindex="-1"])'));
        if (!els.length) return;
        const first = els[0], last = els[els.length - 1];
        if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
        else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
      }
    };
    window.addEventListener('keydown', onKey);
    return () => { window.clearTimeout(t); window.removeEventListener('keydown', onKey); prev?.focus?.(); };
  }, [open, onClose, dismissible]);
  return ref;
}

export function Modal({ open, onClose, title, description, children, footer, size = 'md', dismissible = true, className, icon }: ModalProps) {
  const ref = useDialog(open, onClose, dismissible);
  if (!open) return null;
  return createPortal(
    <div className="fixed inset-0 z-[800] flex items-start justify-center overflow-y-auto p-4 pt-[12vh]">
      <div className="fixed inset-0 bg-black/70 backdrop-blur-[3px] animate-fade-in" onClick={() => dismissible && onClose()} />
      <div
        ref={ref} role="dialog" aria-modal="true" tabIndex={-1}
        className={cn('relative w-full nx-glass rounded-2xl animate-pop-in outline-none', msz[size], className)}
      >
        <div className="absolute inset-x-8 -top-px h-px bg-gradient-to-r from-transparent via-pink/70 to-transparent" />
        {(title || dismissible) && (
          <div className="flex items-start gap-3 px-5 pt-4 pb-2">
            {icon && <div className="mt-0.5 text-pink">{icon}</div>}
            <div className="flex-1 min-w-0">
              {title && <h2 className="text-[15px] font-semibold text-ink">{title}</h2>}
              {description && <p className="mt-0.5 text-sm text-muted">{description}</p>}
            </div>
            {dismissible && (
              <button data-close onClick={onClose} aria-label="Close" className="-mr-1 rounded-md p-1 text-muted hover:text-ink hover:bg-white/5">
                <X size={16} />
              </button>
            )}
          </div>
        )}
        <div className="px-5 py-3">{children}</div>
        {footer && <div className="flex items-center justify-end gap-2 border-t border-line/70 px-5 py-3">{footer}</div>}
      </div>
    </div>,
    document.body,
  );
}

export interface DrawerProps extends Omit<ModalProps, 'size'> { side?: 'right' | 'left'; width?: number }
export function Drawer({ open, onClose, title, description, children, footer, side = 'right', width = 560, dismissible = true, className, icon }: DrawerProps) {
  const ref = useDialog(open, onClose, dismissible);
  if (!open) return null;
  return createPortal(
    <div className="fixed inset-0 z-[800]">
      <div className="absolute inset-0 bg-black/60 backdrop-blur-[2px] animate-fade-in" onClick={() => dismissible && onClose()} />
      <div
        ref={ref} role="dialog" aria-modal="true" tabIndex={-1} style={{ width: `min(${width}px, 100vw)` }}
        className={cn('absolute top-0 bottom-0 flex flex-col bg-panel border-line shadow-panel outline-none animate-slide-in-right',
          side === 'right' ? 'right-0 border-l' : 'left-0 border-r', className)}
      >
        <div className="flex items-start gap-3 px-5 py-4 border-b border-line">
          {icon && <div className="mt-0.5 text-pink">{icon}</div>}
          <div className="flex-1 min-w-0">
            {title && <h2 className="text-[15px] font-semibold truncate">{title}</h2>}
            {description && <p className="mt-0.5 text-sm text-muted">{description}</p>}
          </div>
