export const SLUG_RE = /^[a-z0-9][a-z0-9-]{0,47}$/;
const COLORS = ['#ff3e8a', '#ff6fae', '#ff8a5c', '#b14bff', '#3dffb5', '#ffc857', '#5ce1ff', '#ff4d6d'];

const colorSchema = z.string().regex(/^#[0-9a-fA-F]{6}$/, 'color must be #rrggbb');
const iconSchema = z.string().trim().regex(/^[a-z0-9-]{1,40}$/, 'icon must be a lucide icon name');
const createSchema = z.object({
  name: z.string().trim().min(1).max(80),
  description: z.string().max(2000).optional().default(''),
