import type { FastifyPluginAsync } from 'fastify';
import crypto from 'node:crypto';
import { z } from 'zod';
import { hasRole, requireProject, requireUser, type UserRow } from '../auth.js';
import { AGENT_MODELS, AGENT_SLUG_RE, BUILTIN_BY_SLUG, agentDTO, listAgents, type AgentRow } from '../agents.js';
import type { Ctx } from '../ctx.js';
import { now } from '../db.js';
import { badRequest, conflict, forbidden, notFound } from '../lib/errors.js';

const TOOL_RE = /^[A-Za-z0-9_*:().\- ]{1,200}$/;
const fields = {
  name: z.string().trim().min(1).max(80),
  description: z.string().trim().min(1).max(2000),
  prompt: z.string().trim().min(1).max(50_000),
  tools: z.array(z.string().trim().regex(TOOL_RE, 'invalid tool name')).max(60).nullable(),
  model: z.enum(AGENT_MODELS),
  enabled: z.boolean(),
};
const createSchema = z.object({
  ...fields,
  slug: z.string().trim().regex(AGENT_SLUG_RE, 'slug must be lowercase letters, digits and dashes').optional(),
  tools: fields.tools.optional().default(null),
  model: fields.model.optional().default('inherit'),
  enabled: fields.enabled.optional().default(true),
  scope: z.enum(['global', 'project']),
  projectId: z.string().max(64).nullable().optional(),
});
const patchSchema = z.object({
  name: fields.name.optional(),
  description: fields.description.optional(),
  prompt: fields.prompt.optional(),
  tools: fields.tools.optional(),
  model: fields.model.optional(),
  enabled: fields.enabled.optional(),
  slug: z.string().trim().regex(AGENT_SLUG_RE).optional(),
});

export function agentSlugify(name: string): string {
  const s = name.normalize('NFKD').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 40).replace(/-+$/g, '');
  return s && AGENT_SLUG_RE.test(s) ? s : `agent-${crypto.randomBytes(3).toString('hex')}`;
}

/** Global agents: admins only. Project agents: project editors/owners (and admins). */
function requireAgentWrite(ctx: Ctx, u: UserRow, scope: 'global' | 'project', projectId: string | null) {
  if (scope === 'global') {
    if (u.role !== 'admin') throw forbidden('Only admins can manage global agents');
    return;
  }
  if (!projectId) throw badRequest('projectId is required for project agents', 'missing_project');
  const { role } = requireProject(ctx.db, u, projectId, 'viewer');
  if (!hasRole(role, 'editor')) throw forbidden('Requires editor permission on this project');
}

export default (ctx: Ctx): FastifyPluginAsync =>
  async (app) => {
    const { db } = ctx;
    const load = (id: string) => {
      const a = db.prepare(`SELECT * FROM agents WHERE id = ?`).get(id) as AgentRow | undefined;
      if (!a) throw notFound('Agent not found');
      return a;
    };
    const slugTaken = (scope: 'global' | 'project', projectId: string | null, slug: string, exceptId?: string) =>
      !!(scope === 'global'
        ? db.prepare(`SELECT 1 FROM agents WHERE scope = 'global' AND slug = ? AND id IS NOT ?`).get(slug, exceptId ?? null)
        : db.prepare(`SELECT 1 FROM agents WHERE scope = 'project' AND project_id = ? AND slug = ? AND id IS NOT ?`).get(projectId, slug, exceptId ?? null));

    app.get('/api/agents', async (req) => {
      const u = requireUser(req);
      const projectId = (req.query as { projectId?: string }).projectId || null;
      let canEditProject = false;
      if (projectId) {
        const { role } = requireProject(db, u, projectId, 'viewer');
        canEditProject = hasRole(role, 'editor');
      }
      return listAgents(db, projectId).map((a) => ({
        ...agentDTO(a),
        canEdit: a.scope === 'global' ? u.role === 'admin' : canEditProject,
      }));
    });

    app.post('/api/agents', async (req, reply) => {
      const u = requireUser(req);
      const b = createSchema.parse(req.body ?? {});
      const projectId = b.scope === 'project' ? b.projectId ?? null : null;
      requireAgentWrite(ctx, u, b.scope, projectId);
      let slug = b.slug ?? agentSlugify(b.name);
      if (b.slug && slugTaken(b.scope, projectId, slug)) throw conflict(`An agent named "${slug}" already exists`, 'agent_exists');
      if (!b.slug) {
        const base = slug;
        for (let i = 2; slugTaken(b.scope, projectId, slug); i++) slug = `${base.slice(0, 44)}-${i}`;
      }
      const id = crypto.randomUUID();
      const t = now();
      db.prepare(
        `INSERT INTO agents(id, slug, name, description, prompt, tools, model, scope, project_id, enabled, builtin, created_by, created_at, updated_at)
         VALUES (?,?,?,?,?,?,?,?,?,?,0,?,?,?)`,
      ).run(id, slug, b.name, b.description, b.prompt, b.tools ? JSON.stringify(b.tools) : null, b.model, b.scope, projectId, b.enabled ? 1 : 0, u.id, t, t);
      ctx.audit(req, 'agent_create', id, { slug, scope: b.scope, projectId });
      reply.code(201);
      return { ...agentDTO(load(id)), canEdit: true };
    });

    app.patch('/api/agents/:id', async (req) => {
      const u = requireUser(req);
      const a = load((req.params as { id: string }).id);
      requireAgentWrite(ctx, u, a.scope, a.project_id);
      const b = patchSchema.parse(req.body ?? {});
      if (b.slug !== undefined && b.slug !== a.slug) {
        if (a.builtin) throw badRequest('Built-in agents cannot be renamed', 'builtin');
        if (slugTaken(a.scope, a.project_id, b.slug, a.id)) throw conflict(`An agent named "${b.slug}" already exists`, 'agent_exists');
      }
      db.prepare(
        `UPDATE agents SET slug = COALESCE(?, slug), name = COALESCE(?, name), description = COALESCE(?, description), prompt = COALESCE(?, prompt),
           tools = CASE WHEN ? THEN ? ELSE tools END, model = COALESCE(?, model), enabled = COALESCE(?, enabled), updated_at = ? WHERE id = ?`,
      ).run(
        b.slug ?? null, b.name ?? null, b.description ?? null, b.prompt ?? null,
        b.tools !== undefined ? 1 : 0, b.tools ? JSON.stringify(b.tools) : null,
        b.model ?? null, b.enabled === undefined ? null : b.enabled ? 1 : 0, now(), a.id,
      );
      ctx.audit(req, 'agent_update', a.id, { slug: a.slug, keys: Object.keys(b) });
      return { ...agentDTO(load(a.id)), canEdit: true };
    });

    app.delete('/api/agents/:id', async (req) => {
      const u = requireUser(req);
      const a = load((req.params as { id: string }).id);
      requireAgentWrite(ctx, u, a.scope, a.project_id);
      if (a.builtin) throw conflict('Built-in agents cannot be deleted — disable it instead', 'builtin');
      db.transaction(() => {
        db.prepare(`DELETE FROM agents WHERE id = ?`).run(a.id);
        // conversations led by this agent fall back to the default lead
        if (a.scope === 'project') db.prepare(`UPDATE conversations SET agent_slug = NULL WHERE project_id = ? AND agent_slug = ?`).run(a.project_id, a.slug);
      })();
      ctx.audit(req, 'agent_delete', a.id, { slug: a.slug, scope: a.scope, projectId: a.project_id });
      return { ok: true };
    });

    app.post('/api/agents/:id/reset', async (req) => {
      const u = requireUser(req);
      const a = load((req.params as { id: string }).id);
      requireAgentWrite(ctx, u, a.scope, a.project_id);
      const def = a.builtin ? BUILTIN_BY_SLUG.get(a.slug) : undefined;
      if (!def) throw badRequest('Only built-in agents can be reset', 'not_builtin');
      db.prepare(`UPDATE agents SET name = ?, description = ?, prompt = ?, tools = ?, model = ?, enabled = 1, updated_at = ? WHERE id = ?`).run(
        def.name, def.description, def.prompt, def.tools ? JSON.stringify(def.tools) : null, def.model, now(), a.id,
      );
      ctx.audit(req, 'agent_reset', a.id, { slug: a.slug });
      return { ...agentDTO(load(a.id)), canEdit: true };
    });
  };

