    expect(r.status).toBe(200);
    const slugs = r.json.map((a: any) => a.slug);
    for (const b of BUILTIN_AGENTS) expect(slugs).toContain(b.slug);
    const researcher = r.json.find((a: any) => a.slug === 'researcher');
    expect(researcher).toMatchObject({ scope: 'global', builtin: true, enabled: true, model: 'haiku', modified: false, canEdit: false });
    expect(researcher.tools).toEqual(['WebSearch', 'WebFetch', 'Read']);
    expect(r.json.find((a: any) => a.slug === 'code-reviewer').tools).toEqual(['Read', 'Grep', 'Glob']);
  });

  it('enforces permissions: globals admin-only, project agents editor+', async () => {
    const body = { name: 'Doc Writer', description: 'Writes docs', prompt: 'You write docs.', model: 'haiku', tools: ['Read', 'Write'] };
    expect((await api(env, alice, 'POST', '/api/agents', { ...body, scope: 'global' })).status).toBe(403);
    expect((await api(env, bob, 'POST', '/api/agents', { ...body, scope: 'project', projectId: project.id })).status).toBe(403);
    const created = await api(env, alice, 'POST', '/api/agents', { ...body, scope: 'project', projectId: project.id });
    expect(created.status).toBe(201);
    expect(created.json).toMatchObject({ slug: 'doc-writer', scope: 'project', projectId: project.id, enabled: true, builtin: false });
    // duplicate explicit slug
    expect((await api(env, alice, 'POST', '/api/agents', { ...body, slug: 'doc-writer', scope: 'project', projectId: project.id })).status).toBe(409);
    // invalid model / slug
    expect((await api(env, alice, 'POST', '/api/agents', { ...body, model: 'gpt', scope: 'project', projectId: project.id })).status).toBe(400);
    expect((await api(env, alice, 'POST', '/api/agents', { ...body, slug: 'Bad Slug', scope: 'project', projectId: project.id })).status).toBe(400);
    // bob (viewer) can list but not edit
    const list = (await api(env, bob, 'GET', `/api/agents?projectId=${project.id}`)).json;
    expect(list.find((a: any) => a.slug === 'doc-writer').canEdit).toBe(false);
    expect((await api(env, bob, 'PATCH', `/api/agents/${created.json.id}`, { enabled: false })).status).toBe(403);
    // non-member cannot even list the project's agents
    const outsider = await createUser(env, 'eve@test.local', 'eve-pass');
    expect(outsider).toBeTruthy();
    const eve = await login(env, 'eve@test.local', 'eve-pass');
    expect((await api(env, eve, 'GET', `/api/agents?projectId=${project.id}`)).status).toBe(404);
    // alice edits + deletes her project agent
    const p = await api(env, alice, 'PATCH', `/api/agents/${created.json.id}`, { description: 'Writes great docs', tools: null });
    expect(p.status).toBe(200);
    expect(p.json).toMatchObject({ description: 'Writes great docs', tools: null });
    expect((await api(env, alice, 'DELETE', `/api/agents/${created.json.id}`)).status).toBe(200);
  });

  it('builtins: admin can edit/disable, not delete, and reset', async () => {
    const list = (await api(env, admin, 'GET', '/api/agents')).json;
