    const r = await api(env, alice, 'POST', `/api/conversations/${conv.id}/prompt`, { text: 'ask [delegate]', agent: 'mathbot', model: 'haiku' });
    expect(r.status).toBe(200);
    await waitFor(() => isFinal(runStatus(r.json.runId)?.status));
    const body = env.fake.bodies.at(-1)! as any;
    expect(Object.keys(body.agents)).toContain('mathbot');
    expect(Object.keys(body.agents)).toContain('researcher');
    expect(Object.keys(body.agents)).not.toContain('deployer');
    expect(body.agents.mathbot).toEqual({ description: 'Arithmetic', prompt: 'You do math.', model: 'haiku' });
    expect(body.agents['code-reviewer'].tools).toEqual(['Read', 'Grep', 'Glob']);
    expect(body.agent).toBe('mathbot');
    expect(body.autocompactTokens).toBe(80000);
    expect(body.appendSystemPrompt).toContain('- mathbot: Arithmetic');
    expect(body.appendSystemPrompt).toContain('Delegate to a subagent only when it clearly saves effort');
    expect(body.appendSystemPrompt).toContain('TOKEN BUDGET');

    // subagent usage (parentId) is part of the run totals even though result.usage excludes it
    const run = runStatus(r.json.runId);
    expect(run.input_tokens).toBe(1010);
    expect(run.output_tokens).toBe(55);
    // subagent text never leaks into the answer
    const msgs = (await api(env, alice, 'GET', `/api/conversations/${conv.id}/messages`)).json;
    expect(msgs[1].content).toBe('The answer is 42.');
    expect(msgs[1].events.some((e: any) => e.type === 'text' && e.data.parentId === 'ag1')).toBe(true);
    // conversation remembers the lead agent + context size
    const c2 = (await api(env, alice, 'GET', `/api/conversations/${conv.id}`)).json;
    expect(c2).toMatchObject({ agentSlug: 'mathbot', contextTokens: 1010 });

    // next prompt without `agent` keeps it; disabling the agent drops it silently
    await api(env, alice, 'PATCH', `/api/agents/${mine.id}`, { enabled: false });
