    await api(env, admin, 'PATCH', `/api/agents/${deployer.id}`, { enabled: false });
    const mine = (await api(env, alice, 'POST', '/api/agents', { name: 'Mathbot', description: 'Arithmetic', prompt: 'You do math.', model: 'haiku', scope: 'project', projectId: project.id })).json;

    const conv = await newConv();
    expect(conv).toMatchObject({ contextTokens: null, contextWindow: 200000, agentSlug: null });
    expect((await api(env, alice, 'POST', `/api/conversations/${conv.id}/prompt`, { text: 'hi', agent: 'nope' })).status).toBe(400);
    const r = await api(env, alice, 'POST', `/api/conversations/${conv.id}/prompt`, { text: 'ask [delegate]', agent: 'mathbot', model: 'haiku' });
    expect(r.status).toBe(200);
    await waitFor(() => isFinal(runStatus(r.json.runId)?.status));
    const body = env.fake.bodies.at(-1)! as any;
    expect(Object.keys(body.agents)).toContain('mathbot');
    expect(Object.keys(body.agents)).toContain('researcher');
    expect(Object.keys(body.agents)).not.toContain('deployer');
    expect(body.agents.mathbot).toEqual({ description: 'Arithmetic', prompt: 'You do math.', model: 'haiku' });
    expect(body.agents['code-reviewer'].tools).toEqual(['Read', 'Grep', 'Glob']);
    expect(body.agent).toBe('mathbot');
    expect(body.autocompactTokens).toBe(80000);
    expect(body.appendSystemPrompt).toContain('- mathbot: Arithmetic');
    expect(body.appendSystemPrompt).toContain('Delegate to a subagent only when it clearly saves effort');
    expect(body.appendSystemPrompt).toContain('TOKEN BUDGET');

    // subagent usage (parentId) is part of the run totals even though result.usage excludes it
    const run = runStatus(r.json.runId);
    expect(run.input_tokens).toBe(1010);
    expect(run.output_tokens).toBe(55);
    // subagent text never leaks into the answer
    const msgs = (await api(env, alice, 'GET', `/api/conversations/${conv.id}/messages`)).json;
    expect(msgs[1].content).toBe('The answer is 42.');
    expect(msgs[1].events.some((e: any) => e.type === 'text' && e.data.parentId === 'ag1')).toBe(true);
    // conversation remembers the lead agent + context size
    const c2 = (await api(env, alice, 'GET', `/api/conversations/${conv.id}`)).json;
    expect(c2).toMatchObject({ agentSlug: 'mathbot', contextTokens: 1010 });

    // next prompt without `agent` keeps it; disabling the agent drops it silently
    await api(env, alice, 'PATCH', `/api/agents/${mine.id}`, { enabled: false });
    const r2 = await api(env, alice, 'POST', `/api/conversations/${conv.id}/prompt`, { text: 'again', model: 'haiku' });
    await waitFor(() => isFinal(runStatus(r2.json.runId)?.status));
    const b2 = env.fake.bodies.at(-1)! as any;
    expect(b2.agent).toBeUndefined();
    expect(Object.keys(b2.agents)).not.toContain('mathbot');
    // PATCH conversation agent
    expect((await api(env, alice, 'PATCH', `/api/conversations/${conv.id}`, { agentSlug: 'mathbot' })).status).toBe(400);
    expect((await api(env, alice, 'PATCH', `/api/conversations/${conv.id}`, { agentSlug: 'researcher' })).json.agentSlug).toBe('researcher');
    expect((await api(env, alice, 'PATCH', `/api/conversations/${conv.id}`, { agentSlug: null })).json.agentSlug).toBe(null);
    await api(env, admin, 'POST', `/api/agents/${deployer.id}/reset`);
  });

  it('system prompt lists agents only when there are some', () => {
    const p = { slug: 'x', name: 'X', description: '', preview_port: 4100, preview_strip: 0 } as any;
    expect(buildSystemPrompt(p, env.cfg)).not.toContain('SUBAGENTS');
    expect(buildSystemPrompt(p, env.cfg, [{ slug: 'a', description: 'does A' }])).toContain('- a: does A');
  });
});

describe('compact', () => {
  it('409 without a session; compacts, stores kind, context tokens, usage', async () => {
    const conv = await newConv();
    expect((await api(env, alice, 'POST', `/api/conversations/${conv.id}/compact`, {})).status).toBe(409);
    const r = await api(env, alice, 'POST', `/api/conversations/${conv.id}/prompt`, { text: 'hello', model: 'haiku' });
    await waitFor(() => isFinal(runStatus(r.json.runId)?.status));
    expect((await api(env, bob, 'POST', `/api/conversations/${conv.id}/compact`, {})).status).toBe(403);

    const c = await api(env, alice, 'POST', `/api/conversations/${conv.id}/compact`, { instructions: '  keep the\nAPI notes ' });
    expect(c.status).toBe(200);
    // a second compact while running → 409
    const again = await api(env, alice, 'POST', `/api/conversations/${conv.id}/compact`, {});
    expect([409, 200]).toContain(again.status); // may already be finished with the fast fake
    await waitFor(() => isFinal(runStatus(c.json.runId)?.status));
    const body = env.fake.bodies.find((b: any) => b.runId === c.json.runId) as any;
    expect(body).toMatchObject({ prompt: '/compact keep the API notes', sessionId: 'sess-1', thinking: 'off' });
    expect(body.agents).toBeUndefined();
    expect(runStatus(c.json.runId)).toMatchObject({ status: 'done', output_tokens: 3200, cache_read: 52100 });

    const msgs = (await api(env, alice, 'GET', `/api/conversations/${conv.id}/messages`)).json;
    const compactMsgs = msgs.filter((m: any) => m.kind === 'compact');
    expect(compactMsgs.map((m: any) => m.role)).toEqual(['user', 'assistant']);
    expect(compactMsgs[1].events.find((e: any) => e.type === 'compact').data).toMatchObject({ preTokens: 52100, postTokens: 3200 });
    expect(msgs.filter((m: any) => !m.kind).every((m: any) => m.kind === undefined)).toBe(true);
    const c2 = (await api(env, alice, 'GET', `/api/conversations/${conv.id}`)).json;
    expect(c2.contextTokens).toBe(3200);
    // conversation title not changed by compaction
    expect(c2.title).toBe('Hello');
  });

