    expect((await api(env, admin, 'PATCH', '/api/admin/settings', { autoCompactTokens: 0 })).json.autoCompactTokens).toBe(0);
    const conv = await newConv();
    const r = await api(env, alice, 'POST', `/api/conversations/${conv.id}/prompt`, { text: 'x', model: 'haiku' });
    await waitFor(() => isFinal(runStatus(r.json.runId)?.status));
    expect((env.fake.bodies.at(-1) as any).autocompactTokens).toBeUndefined();
    await api(env, admin, 'PATCH', '/api/admin/settings', { autoCompactTokens: 80000 });
  });
});
