export function Field({ label, hint, error, htmlFor, children, className }: {
  label?: ReactNode; hint?: ReactNode; error?: ReactNode; htmlFor?: string; children: ReactNode; className?: string;
}) {
  return (
    <div className={cn('flex flex-col gap-1.5', className)}>
      {label && <label htmlFor={htmlFor} className="text-xs font-medium text-muted">{label}</label>}
      {children}
      {error ? <p className="text-xs text-bad">{error}</p> : hint ? <p className="text-xs text-muted/80">{hint}</p> : null}
    </div>
  );
}

