// Context meter for the active conversation: "Context 48k" bar, warm → danger as it nears the
// auto-compact threshold. Click → compact now (with optional instructions).
import { useState } from 'react';
import clsx from 'clsx';
import { FoldVertical } from 'lucide-react';
import { useWs } from './store';
import { fmtTokens } from './toolFormat';
import { Popover, Tip } from './ui';

export function ContextMeter({ busy }: { busy: boolean }) {
  const conv = useWs((s) => s.conversations.find((c) => c.id === s.activeConvId));
  const threshold = useWs((s) => s.usage?.context?.autoCompactTokens) ?? 80_000;
  const compact = useWs((s) => s.compact);
  const [open, setOpen] = useState(false);
  const [el, setEl] = useState<HTMLElement | null>(null);
  const [instr, setInstr] = useState('');
  const [sending, setSending] = useState(false);
  const tokens = conv?.contextTokens ?? 0;
  if (!conv || !tokens) return null;
  const r = Math.min(1, tokens / threshold);
  // warm until ~40% of the threshold, then blend towards danger
  const heat = Math.round(Math.max(0, Math.min(1, (r - 0.4) / 0.55)) * 100);
  const color = `color-mix(in srgb, var(--danger) ${heat}%, var(--warm))`;
  const canCompact = !!conv.claudeSessionId && !busy;
  const go = async () => {
    setSending(true);
    const ok = await compact(instr);
    setSending(false);
    if (ok) { setInstr(''); setOpen(false); }
  };
  return (
    <>
      <Tip label={`${tokens.toLocaleString()} tokens in context · auto-compacts at ${fmtTokens(threshold)} · click to compact`}>
        <button ref={setEl} type="button" onClick={() => setOpen((o) => !o)}
          className={clsx('hidden h-7 items-center gap-1.5 rounded-lg px-2 font-mono text-[11px] transition-colors sm:inline-flex',
            open ? 'bg-white/[.06] text-ink' : 'text-muted hover:bg-white/[.05] hover:text-ink')}>
          <span>Context {fmtTokens(tokens)}</span>
          <span className="h-1 w-12 overflow-hidden rounded-full bg-white/[.07]">
            <span className="block h-full rounded-full transition-[width] duration-500" style={{ width: `${Math.max(4, r * 100)}%`, background: color, boxShadow: r > 0.85 ? `0 0 8px ${color}` : undefined }} />
          </span>
        </button>
      </Tip>
      <Popover open={open} anchor={el} onClose={() => setOpen(false)} align="end" className="w-[300px]">
        <div className="space-y-2.5 p-2">
          <div>
            <div className="text-[10.5px] uppercase tracking-[.14em] text-muted">Context window</div>
            <div className="mt-1 flex items-baseline gap-1.5">
              <span className="font-mono text-[15px] text-ink">{fmtTokens(tokens)}</span>
              <span className="text-[12px] text-muted">/ {fmtTokens(threshold)} before auto-compact</span>
            </div>
            <div className="mt-1.5 h-1.5 overflow-hidden rounded-full bg-white/[.06]">
              <div className="h-full rounded-full" style={{ width: `${Math.max(2, r * 100)}%`, background: color }} />
            </div>
            <p className="mt-2 text-[11.5px] leading-snug text-muted">
              Every message re-reads this context. Compacting summarizes the conversation so far, so follow-ups are cheaper.
            </p>
          </div>
          <textarea value={instr} onChange={(e) => setInstr(e.target.value)} rows={2} maxLength={2000}
            placeholder="Optional: what to keep (e.g. the API design decisions)"
            className="nxw-scroll w-full resize-none rounded-lg border border-line bg-bg/60 px-2.5 py-1.5 text-[12.5px] text-ink outline-none placeholder:text-muted/50 focus:border-pink/60"
            onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey && canCompact) { e.preventDefault(); go(); } }} />
          <button type="button" onClick={go} disabled={!canCompact || sending}
            className="flex w-full items-center justify-center gap-1.5 rounded-lg border border-warm/40 bg-warm/10 px-3 py-1.5 text-[12.5px] text-warm transition hover:bg-warm/20 disabled:pointer-events-none disabled:opacity-40">
            {sending ? <span className="h-3 w-3 animate-spin rounded-full border-2 border-warm/30 border-t-warm" /> : <FoldVertical size={13} />}
            Compact now
          </button>
          {busy && <div className="text-center text-[11px] text-muted">Wait for the current run to finish.</div>}
        </div>
      </Popover>
    </>
  );
}

