// Agents (Claude Code subagents) manager — used in the workspace drawer (global + project agents)
// and on /admin/agents (global agents only).
import { useCallback, useEffect, useMemo, useState } from 'react';
import { ArrowLeft, Bot, Pencil, Plus, RotateCcw, Trash2 } from 'lucide-react';
import { api } from '@/lib/api';
import type { Agent, AgentModel } from '@/lib/types';
import { Badge, Button, Input, Skeleton, Switch, Textarea, cn, toast } from '@/components/ui';

export const KNOWN_TOOLS = ['Read', 'Write', 'Edit', 'Glob', 'Grep', 'Bash', 'WebSearch', 'WebFetch', 'TodoWrite', 'NotebookEdit', 'Agent'];
const MODELS: { id: AgentModel; label: string; hint: string }[] = [
  { id: 'inherit', label: 'Inherit', hint: 'same as the conversation' },
  { id: 'haiku', label: 'Haiku', hint: 'fast & cheap' },
  { id: 'sonnet', label: 'Sonnet', hint: 'balanced' },
  { id: 'opus', label: 'Opus', hint: 'most capable' },
];

interface Draft {
  id?: string; slug: string; name: string; description: string; prompt: string; tools: string[] | null;
  model: AgentModel; scope: 'global' | 'project'; enabled: boolean; builtin?: boolean; modified?: boolean;
}
const blank = (scope: Draft['scope']): Draft => ({ slug: '', name: '', description: '', prompt: '', tools: null, model: 'inherit', scope, enabled: true });
const slugify = (s: string) => s.toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 40);

export function AgentsPanel({ projectId, isAdmin, onChanged }: { projectId: string | null; isAdmin: boolean; onChanged?: () => void }) {
  const [agents, setAgents] = useState<Agent[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [edit, setEdit] = useState<Draft | null>(null);
  const load = useCallback(async () => {
    try {
      setAgents(await api.get<Agent[]>(`/agents${projectId ? `?projectId=${encodeURIComponent(projectId)}` : ''}`));
      setError(null);
    } catch (e: any) { setError(e.message || 'Failed to load agents'); }
  }, [projectId]);
  useEffect(() => { load(); }, [load]);
  const changed = () => { load(); onChanged?.(); };

  const toggle = async (a: Agent, enabled: boolean) => {
    setAgents((l) => l?.map((x) => (x.id === a.id ? { ...x, enabled } : x)) ?? l);
    try { await api.patch(`/agents/${a.id}`, { enabled }); changed(); }
    catch (e: any) { toast.error(e.message); load(); }
  };

  if (edit) return <AgentForm draft={edit} projectId={projectId} isAdmin={isAdmin} onDone={(saved) => { setEdit(null); if (saved) changed(); }} />;
  if (error) return <div className="rounded-lg border border-bad/30 bg-bad/[.06] px-3 py-2 text-sm text-bad">{error}</div>;
  if (!agents) return <div className="space-y-2"><Skeleton className="h-14" /><Skeleton className="h-14" /><Skeleton className="h-14" /></div>;

  const project = agents.filter((a) => a.scope === 'project');
  const global = agents.filter((a) => a.scope === 'global');
  const shadowed = new Set(project.map((a) => a.slug));
  const canCreateProject = !!projectId && (agents.some((a) => a.scope === 'project' ? a.canEdit : false) || project.length === 0);
  const toDraft = (a: Agent): Draft => ({ id: a.id, slug: a.slug, name: a.name, description: a.description, prompt: a.prompt, tools: a.tools, model: a.model, scope: a.scope, enabled: a.enabled, builtin: a.builtin, modified: a.modified });

  return (
    <div className="space-y-6">
      <p className="text-[13px] leading-relaxed text-muted">
        Subagents are specialists Claude can delegate to (each with its own prompt, tools and model). Claude decides when to use them
        based on the description — or type <span className="font-mono text-hot">@name</span> in a prompt to ask for one.
      </p>
      {projectId && (
        <Section title="This project" action={canCreateProject && <Button size="xs" variant="outline" icon={<Plus size={12} />} onClick={() => setEdit(blank('project'))}>New agent</Button>}>
          {project.length ? project.map((a) => <Row key={a.id} a={a} onToggle={toggle} onEdit={() => setEdit(toDraft(a))} />)
            : <div className="rounded-lg border border-dashed border-line px-3 py-4 text-center text-[12.5px] text-muted">No project agents yet.</div>}
        </Section>
      )}
      <Section title="Global" hint={isAdmin ? 'Available in every project' : 'Managed by admins'}
        action={isAdmin && <Button size="xs" variant={projectId ? 'ghost' : 'outline'} icon={<Plus size={12} />} onClick={() => setEdit(blank('global'))}>New global agent</Button>}>
        {global.map((a) => <Row key={a.id} a={a} shadowed={shadowed.has(a.slug)} onToggle={toggle} onEdit={() => setEdit(toDraft(a))} />)}
      </Section>
    </div>
  );
}

function Section({ title, hint, action, children }: { title: string; hint?: string; action?: React.ReactNode; children: React.ReactNode }) {
  return (
    <section>
      <div className="mb-2 flex items-center gap-2">
        <h3 className="text-[11px] font-medium uppercase tracking-[.16em] text-pink/80">{title}</h3>
        {hint && <span className="text-[11.5px] text-muted">· {hint}</span>}
        <span className="ml-auto">{action}</span>
      </div>
      <div className="space-y-1.5">{children}</div>
    </section>
  );
}

function Row({ a, shadowed, onToggle, onEdit }: { a: Agent; shadowed?: boolean; onToggle: (a: Agent, v: boolean) => void; onEdit: () => void }) {
  return (
    <div className={cn('group flex items-start gap-3 rounded-xl border border-line bg-panel2/40 px-3 py-2.5 transition-colors hover:border-pink/25', (!a.enabled || shadowed) && 'opacity-60')}>
      <div className={cn('mt-0.5 flex h-7 w-7 shrink-0 items-center justify-center rounded-lg border', a.enabled ? 'border-violet/40 bg-violet/10 text-violet' : 'border-line text-muted')}>
        <Bot size={14} />
      </div>
      <div className="min-w-0 flex-1">
        <div className="flex flex-wrap items-center gap-x-2 gap-y-0.5">
          <span className="text-[13.5px] font-medium text-ink">{a.name}</span>
          <span className="font-mono text-[11px] text-muted">@{a.slug}</span>
          <Badge tone={a.model === 'haiku' ? 'ok' : a.model === 'opus' ? 'violet' : a.model === 'sonnet' ? 'pink' : 'neutral'}>{a.model}</Badge>
          {a.builtin && <Badge>{a.modified ? 'built-in · edited' : 'built-in'}</Badge>}
          {shadowed && <Badge tone="warn">overridden here</Badge>}
        </div>
        <div className="mt-0.5 line-clamp-2 text-[12.5px] leading-snug text-muted">{a.description}</div>
        <div className="mt-1 truncate font-mono text-[10.5px] text-muted/70">{a.tools ? a.tools.join(' · ') || 'no tools' : 'all tools'}</div>
      </div>
      <div className="flex shrink-0 items-center gap-1">
        {a.canEdit && (
          <button type="button" onClick={onEdit} aria-label={`Edit ${a.name}`}
            className="rounded-md p-1.5 text-muted opacity-60 transition hover:bg-white/5 hover:text-ink group-hover:opacity-100"><Pencil size={13} /></button>
        )}
        <Switch size="sm" checked={a.enabled} disabled={!a.canEdit} onChange={(v) => onToggle(a, v)} />
      </div>
    </div>
  );
}

function AgentForm({ draft, projectId, isAdmin, onDone }: { draft: Draft; projectId: string | null; isAdmin: boolean; onDone: (saved: boolean) => void }) {
  const [d, setD] = useState<Draft>(draft);
  const [slugTouched, setSlugTouched] = useState(!!draft.id);
  const [busy, setBusy] = useState(false);
  const isNew = !draft.id;
  const set = (p: Partial<Draft>) => setD((x) => ({ ...x, ...p }));
  const slugOk = /^[a-z0-9][a-z0-9-]{0,47}$/.test(d.slug);
  const valid = d.name.trim() && d.description.trim() && d.prompt.trim() && slugOk;
  const toolSet = useMemo(() => new Set(d.tools ?? []), [d.tools]);

  const save = async () => {
    if (!valid) return;
    setBusy(true);
    try {
      const body = { name: d.name.trim(), description: d.description.trim(), prompt: d.prompt.trim(), tools: d.tools, model: d.model, enabled: d.enabled };
      if (isNew) await api.post('/agents', { ...body, slug: d.slug, scope: d.scope, projectId: d.scope === 'project' ? projectId : null });
      else await api.patch(`/agents/${d.id}`, { ...body, ...(d.builtin ? {} : { slug: d.slug }) });
      toast.success(isNew ? 'Agent created' : 'Agent saved');
      onDone(true);
    } catch (e: any) { toast.error('Save failed', { description: e.message }); } finally { setBusy(false); }
  };
  const del = async () => {
    if (!d.id || !confirm(`Delete agent "${d.name}"?`)) return;
    setBusy(true);
    try { await api.del(`/agents/${d.id}`); toast.success('Agent deleted'); onDone(true); }
    catch (e: any) { toast.error(e.message); setBusy(false); }
  };
  const reset = async () => {
    if (!d.id || !confirm('Restore the built-in definition? Your edits to this agent are lost.')) return;
    setBusy(true);
    try { await api.post(`/agents/${d.id}/reset`); toast.success('Agent reset'); onDone(true); }
    catch (e: any) { toast.error(e.message); setBusy(false); }
  };

  return (
    <div className="space-y-4">
      <button type="button" onClick={() => onDone(false)} className="flex items-center gap-1.5 text-[12.5px] text-muted hover:text-ink">
        <ArrowLeft size={13} /> All agents
      </button>
      <div className="grid gap-3 sm:grid-cols-2">
        <Input label="Name" value={d.name} autoFocus placeholder="API designer"
          onChange={(e) => set({ name: e.target.value, ...(!slugTouched ? { slug: slugify(e.target.value) } : {}) })} />
        <Input label="Handle" mono value={d.slug} disabled={d.builtin} placeholder="api-designer"
          onChange={(e) => { setSlugTouched(true); set({ slug: e.target.value.toLowerCase() }); }}
          error={d.slug && !slugOk ? 'lowercase letters, digits, dashes' : undefined} hint={d.slug ? `@${d.slug}` : undefined} />
      </div>
      <Textarea label="When to delegate" rows={2} value={d.description} placeholder="Designs REST endpoints and reviews API consistency. Use when adding or changing endpoints."
        hint="Claude reads this to decide when to use the agent — be specific." onChange={(e) => set({ description: e.target.value })} />
      <Textarea label="System prompt" mono rows={9} autosize={false} value={d.prompt} placeholder="You are an expert … Report back concisely with …"
        onChange={(e) => set({ prompt: e.target.value })} />
      <div>
        <div className="mb-1.5 text-xs font-medium text-muted">Model</div>
        <div className="grid grid-cols-4 gap-1.5">
          {MODELS.map((m) => (
            <button key={m.id} type="button" onClick={() => set({ model: m.id })}
              className={cn('rounded-lg border px-2 py-1.5 text-left transition-colors', d.model === m.id ? 'border-pink/60 bg-pink/10' : 'border-line hover:border-pink/30')}>
              <div className="text-[12.5px] text-ink">{m.label}</div>
              <div className="text-[10.5px] text-muted">{m.hint}</div>
            </button>
          ))}
        </div>
      </div>
      <div>
        <div className="mb-1.5 flex items-center gap-3">
          <span className="text-xs font-medium text-muted">Tools</span>
          <Switch size="sm" checked={d.tools === null} onChange={(v) => set({ tools: v ? null : ['Read', 'Grep', 'Glob'] })} label={<span className="text-[12px] text-muted">Inherit all tools</span>} />
        </div>
        {d.tools !== null && (
          <div className="flex flex-wrap gap-1.5">
            {KNOWN_TOOLS.map((t) => {
              const on = toolSet.has(t);
              return (
                <button key={t} type="button" onClick={() => set({ tools: on ? d.tools!.filter((x) => x !== t) : [...d.tools!, t] })}
                  className={cn('rounded-full border px-2.5 py-1 font-mono text-[11.5px] transition-colors', on ? 'border-violet/50 bg-violet/15 text-ink' : 'border-line text-muted hover:border-violet/30')}>
                  {t}
                </button>
              );
            })}
          </div>
        )}
      </div>
      {isNew && projectId && isAdmin && (
        <div>
          <div className="mb-1.5 text-xs font-medium text-muted">Scope</div>
          <div className="flex gap-1.5">
            {(['project', 'global'] as const).map((sc) => (
              <button key={sc} type="button" onClick={() => set({ scope: sc })}
                className={cn('rounded-lg border px-3 py-1.5 text-[12.5px]', d.scope === sc ? 'border-pink/60 bg-pink/10 text-ink' : 'border-line text-muted hover:border-pink/30')}>
                {sc === 'project' ? 'This project' : 'All projects'}
              </button>
            ))}
          </div>
        </div>
      )}
      <div className="flex items-center gap-2 border-t border-line/70 pt-3">
        {!isNew && !d.builtin && <Button size="sm" variant="ghost" icon={<Trash2 size={13} />} onClick={del} disabled={busy}>Delete</Button>}
        {!isNew && d.builtin && d.modified && <Button size="sm" variant="ghost" icon={<RotateCcw size={13} />} onClick={reset} disabled={busy}>Reset to default</Button>}
        <span className="ml-auto" />
        <Button size="sm" variant="ghost" onClick={() => onDone(false)}>Cancel</Button>
        <Button size="sm" variant="primary" loading={busy} disabled={!valid} onClick={save}>{isNew ? 'Create agent' : 'Save'}</Button>
      </div>
    </div>
  );
}

